/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A33 staging · 80-word manifest: facilitator–fertiliser */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('facilitator','facilitate 来自拉丁语 facilis“容易的”，经法语进入英语；facilitator 是动词加施事者后缀 -or，指帮助群体顺利交流的人。',C('facilitator.s1','会议协作','The facilitator invited the quiet participants to speak first, then summarized the competing ideas without telling the group which one to choose.','引导人先邀请沉默的参与者发言，再概括彼此不同的想法，但没有替小组决定选哪一个。','The facilitator invited the quiet participants to speak first / then summarized the competing ideas / without telling the group which one to choose.','facilitator 是帮助讨论顺利进行的人；invite somebody to do 与 summarize ideas 说明其引导而非代决策。','主持者促进成员参与、整理观点而不替他们下结论，符合引导者义。'),M('The facilitator made every decision alone and forbade the group from contributing.','The director made every decision alone and forbade the group from contributing.','独自决策并禁止参与者发言与“促进小组参与”的 facilitator 职责相反。'),[Q('facilitator',1,1,'At a workshop, a facilitator mainly helps participants to?','exchange ideas and keep the discussion productive','receive a final grade from the instructor','repair the room’s heating system','facilitator 引导交流、帮助群体完成讨论。'),Q('facilitator',2,1,'Which action best shows facilitation rather than lecturing?','asking each team to compare its evidence','speaking for the whole session without questions','announcing a decision before anyone arrives','邀请成员分析证据比单向讲授更体现引导。'),Q('facilitator',3,1,'A neutral facilitator should usually?','help the group reach its own decision','choose a side before hearing the members','replace every participant’s proposal','引导者帮助成员讨论，不应预先替他们决定。'),Q('facilitator',4,1,'In “The facilitator drew out two quiet voices,” drew out means?','encouraged them to contribute','asked them to leave the room','copied their words into a report','draw out 在会议语境里是鼓励其表达。')]);
P('facsimile','facsimile 经法语借自拉丁语 fac simile，字面为“做成相似的东西”；现代常指精确复制件，也曾指传真传送。',C('facsimile.s2','文献复制','The archive displayed a facsimile of the handwritten map, allowing visitors to inspect its faded annotations while the fragile original remained in storage.','档案馆展出手绘地图的摹真复制件，让参观者查看褪色的注释，同时把易损原件留在库房中。','The archive displayed a facsimile of the handwritten map / allowing visitors to inspect its faded annotations / while the fragile original remained in storage.','a facsimile of + 原件；while 从句对照可供查看的复制品与受保护原件。','复制品保留手稿外观细节，且原件另行保存，体现精确复制本义。'),M('The museum called a blurry, freely redrawn map a facsimile even though its labels and scale had all changed.','The museum called a blurry, freely redrawn map an adaptation because its labels and scale had changed.','facsimile 强调忠实精确的复制；内容和比例均改变时称 adaptation 更准确。'),[Q('facsimile',1,2,'Why might a library show a facsimile instead of a manuscript?','the copy can be handled while the original is protected','the copy is guaranteed to contain new chapters','the original has been converted into a sculpture','复制件便于接触，能保护珍贵原件。'),Q('facsimile',2,1,'In the older office instruction “send it by facsimile,” the document should be?','transmitted by fax','translated into another language','mailed as an unsigned blank','facsimile 也可指传真传送。'),Q('facsimile',3,2,'Which object is most accurately a facsimile?','a page reproduced to preserve the original layout','a summary that omits half the pages','a painting inspired by the page’s subject','保留原版式的复制页符合精确复制义。'),Q('facsimile',4,3,'As a verb, to facsimile a page is to?','send or reproduce it exactly','remove every trace of its text','write a new ending for it','动词 facsimile 表示传真发送或精确复制。')]);
P('factious','factious 由 faction（派系）加形容词后缀 -ious 构成；faction 源自拉丁语 factio“结党、派别”，形容热衷派争或由其引发的事物。',C('factious.s2','组织政治','The board’s factious election campaign split members into rival camps, and meetings became arguments over loyalty rather than plans for the school.','董事会中派系纷争不断的选举活动把成员分成对立阵营，会议变成争论忠诚问题，而不是讨论学校计划。','The board’s factious election campaign / split members into rival camps / and meetings became arguments over loyalty / rather than plans for the school.','factious 可修饰引发派系争斗的活动；split A into camps 表示分裂成阵营。','竞选造成相互敌对的阵营和争斗，体现“由派系纷争引起的”s2。'),M('The factious council worked as one united team, welcomed disagreement, and never formed rival camps.','The harmonious council worked as one united team, welcomed disagreement, and never formed rival camps.','团结协作、没有对立派系与 factious 的派系纷争义冲突。'),[Q('factious',1,2,'A factious election inside an association is marked by?','quarrels among rival groups','a single candidate running unopposed','a unanimous decision made without debate','factious 描述派系对立和争斗。'),Q('factious',2,1,'A factious member is most likely to?','help form a faction that fights other members','avoid all groups and work alone','settle every dispute impartially','s1 指爱搞派系、引发争斗的人。'),Q('factious',3,2,'Which outcome suggests factious politics?','members vote in hostile blocs against one another','members compare plans and agree on shared goals','members postpone a vote because the room is closed','敌对阵营彼此投票对抗体现派争。'),Q('factious',4,1,'The closest opposite of a factious group is a?','united group','rival faction','divisive clique','united 与派系分裂相反。')]);
P('factitious','factitious 源自拉丁语 facticius“人工制造的”，与 facere“做”有关；形容人为造出、缺乏自然真实性的事物。',C('factitious.s1','社会调查','The survey team rejected the factitious testimonials because one consultant had invented them instead of collecting comments from actual residents.','调查组拒绝了那些人为编造的推荐语，因为一名顾问并未收集真实居民的评论，而是自行捏造。','The survey team rejected the factitious testimonials / because one consultant had invented them / instead of collecting comments from actual residents.','factitious 修饰人为制造、冒充真实的材料；because 从句交代其虚构来源。','推荐语由顾问编造而非真实反馈，符合“人为制造、假装真实”的义项。'),M('The factitious quotations came from verified interviews with named residents and were recorded word for word.','The authentic quotations came from verified interviews with named residents and were recorded word for word.','经核实的真实访谈引语不是人为伪造的，authentic 才符合语境。'),[Q('factitious',1,1,'A factitious excuse is one that is?','invented rather than genuine','supported by a signed receipt','caused by a natural storm','factitious 指人为编造或不自然的。'),Q('factitious',2,1,'Which evidence would make a testimonial factitious?','the advertiser fabricated it without a real customer','a customer gave it after using the product','the shop published it with permission','没有真实顾客却由广告方杜撰，属于人为编造。'),Q('factitious',3,1,'Choose the best contrast for factitious.','authentic','manufactured','artificial','authentic 表示真实可信，与伪造相对。'),Q('factitious',4,1,'A factitious sense of urgency was created by?','a seller pretending stock would vanish when it would not','a genuine safety alarm during a fire','a storm warning issued by meteorologists','假装货物将售罄制造的紧迫感是人为的。')]);
P('factual','factual 由 fact（事实）加形容词后缀 -ual 构成；fact 经法语源自拉丁语 factum“所做之事”，factual 表示基于或忠实于事实。',C('factual.s2','新闻报道','The reporter kept the account factual by separating what witnesses had seen from her own interpretation of why the driver turned.','记者把目击者看到的情况与她对司机转弯原因的个人解释分开，从而保持叙述如实。','The reporter kept the account factual / by separating what witnesses had seen / from her own interpretation / of why the driver turned.','keep an account factual 表示让叙述以事实为据；separate A from B 区分观察与推断。','报道仅陈述实际观察并标出解释界限，符合如实叙述的 s2。'),M('The report was factual because it replaced verified dates with the writer’s imaginary opinions.','The report was fictional because it replaced verified dates with the writer’s imaginary opinions.','以想象意见替换核实日期并非 factual；fictional 表达虚构更合适。'),[Q('factual',1,1,'A factual statement should be based on?','evidence about what actually happened','a speaker’s unsupported preference','a detail invented to improve a story','factual 要以实际事实或证据为依据。'),Q('factual',2,2,'A factual news account avoids presenting a guess as?','a verified event','a personal reaction','an open question','如实报道不把猜测冒充已证实事件。'),Q('factual',3,1,'Which note is factual?','The gauge read 18°C at noon.','The afternoon felt like the worst ever.','The town surely wanted the storm.','仪表读数可核实；其他两句含主观判断或无根据猜测。'),Q('factual',4,1,'Factual differs from opinion because factual claims can be?','checked against evidence','proved only by personal taste','true whenever they sound confident','事实陈述能够用证据检验。')]);
P('fagot','fagot 是较少见的拼法变体，指捆扎起来作柴火的一束枝条；不要与现代贬义词 faggot 混为一谈。',C('fagot.s1','旧式燃料','The tenant stacked a fagot of dry twigs beside the hearth, ready to kindle the fire before the cold evening arrived.','租客把一捆干树枝堆在壁炉旁，准备在寒冷的夜晚到来前点火。','The tenant stacked a fagot of dry twigs beside the hearth / ready to kindle the fire / before the cold evening arrived.','a fagot of + 复数枝条表示一捆柴；kindle the fire 表示点燃。','枝条被捆起并用于生火，符合词典中的柴把义。'),M('The camper called one loose twig a fagot, although it was neither bundled nor intended as a supply of firewood.','The camper called a bundle of dry twigs a fagot, ready to use as firewood.','fagot 指捆扎成束的柴枝；单根散枝并不符合该词义。'),[Q('fagot',1,1,'A fagot of wood is?','a bundle of sticks tied together','a single stone from a fireplace','a metal tool used to measure heat','fagot 指捆成一束的枝条，尤其用作柴火。'),Q('fagot',2,1,'Which scene best fits the historical noun fagot?','bundled twigs carried to a hearth','a log left loose in a river','a glass thermometer on a shelf','捆好的细枝被带去壁炉，符合柴把义。'),Q('fagot',3,1,'Before burning a fagot, someone might?','untie or place the bundle among the kindling','pour it into a cup','use it to record a temperature','柴束可拆开或放入引火物中。'),Q('fagot',4,1,'In this entry, fagot names a kind of?','firewood bundle','weather scale','flying bird','词条义是捆束的柴枝。')]);
P('fahrenheit','fahrenheit 以德国物理学家 Daniel Gabriel Fahrenheit（华伦海特）命名，先作温标名，亦作表示按该温标计量的形容词。',C('fahrenheit.s1','天气读数','The forecast gives the afternoon high as 86 degrees Fahrenheit, which is warm but still below the city’s heat advisory threshold.','天气预报称下午最高温为华氏 86 度，天气偏暖，但仍低于该市高温预警门槛。','The forecast gives the afternoon high as 86 degrees Fahrenheit / which is warm / but still below the city’s heat advisory threshold.','degrees Fahrenheit 表示华氏度；摄氏约 30°C，避免把 86 误读为摄氏度。','温度数字明确按 Fahrenheit 温标报告，体现 s1。'),M('The nurse recorded 98 degrees Fahrenheit as a normal human body temperature.','The nurse recorded 98.6 degrees Fahrenheit as an approximate normal human body temperature.','98°F 低于典型正常体温；若要表达约 37°C，应写约 98.6°F。'),[Q('fahrenheit',1,1,'On the Fahrenheit scale, water freezes at?','32 degrees','0 degrees','100 degrees','水的冰点在华氏温标上是 32 度。'),Q('fahrenheit',2,2,'A temperature reported as 70 Fahrenheit is measured in?','the Fahrenheit scale','the Celsius scale','the Kelvin scale only','Fahrenheit 可作形容词，说明按华氏温标计量。'),Q('fahrenheit',3,1,'Which conversion is approximately correct?','68°F is 20°C','32°F is 32°C','212°F is 100°C below freezing','华氏 68 度约等于摄氏 20 度。'),Q('fahrenheit',4,1,'The thermometer reads 104°F. The number refers to?','degrees on a named temperature scale','the patient’s age in years','the air pressure in millibars','°F 表示华氏温度读数。')]);
P('faintly','faintly 是 faint 加副词后缀 -ly；faint 源自古法语 faindre“变弱、衰退”，此处表示以微弱到几乎察觉不到的程度。',C('faintly.s1','气味与感知','A faintly citrus smell lingered in the hallway, noticeable only when the door to the kitchen opened.','走廊里残留着一丝淡淡的柑橘气味，只有厨房门打开时才闻得到。','A faintly citrus smell lingered in the hallway / noticeable only / when the door to the kitchen opened.','faintly 修饰形容词 citrus，表示气味很淡；linger 表示继续残留。','气味仅微弱可察，符合 faintly 的程度义。'),M('The alarm rang faintly, shaking every window and waking people three streets away.','The alarm rang loudly, shaking every window and waking people three streets away.','震动窗户并惊醒远处居民说明声音很大，与 faintly 相反。'),[Q('faintly',1,1,'If a light shines faintly, it is?','dim and only just visible','bright enough to blind everyone','completely absent','faintly 表示光线微弱、勉强看得见。'),Q('faintly',2,1,'Which sound could be heard faintly?','a distant bell barely audible through the rain','a siren deafening people nearby','a sound that never occurred','远处且几乎听不见的铃声属于微弱声音。'),Q('faintly',3,1,'“She smiled faintly” most likely describes a smile that is?','slight and restrained','wide and unmistakable','angry and shouted','faintly 可表示表情轻微、不明显。'),Q('faintly',4,1,'Choose the natural completion: “The old paint was ___ blue.”','faintly','faint','faintness','副词 faintly 可修饰颜色词 blue，表示颜色很淡。')]);
P('fairground','fairground 由 fair（集市、游乐会）和 ground（场地）组成，指举办游乐会、集市并设有游乐设施的场地。',C('fairground.s1','节庆活动','By dusk, the fairground was bright with ride lights, food stalls, and families waiting near the ferris wheel.','黄昏时，露天游乐场里游乐设施灯火通明，设有食品摊，许多家庭在摩天轮旁排队。','By dusk / the fairground was bright with ride lights, food stalls, and families / waiting near the ferris wheel.','fairground 是举办游乐活动的场地；bright with 列举现场可见设施。','游乐设施、摊位和人群共同表明这是集会游乐场地。'),M('The fairground was an empty office where no fair, rides, or stalls had ever been held.','The venue was an empty office where no fair, rides, or stalls had ever been held.','没有集市和游乐设施的办公室不是 fairground。'),[Q('fairground',1,1,'A fairground is a place where visitors may find?','rides and stalls at a fair','only hospital operating rooms','a permanent courtroom for trials','fairground 是集市或游乐会举行的场地。'),Q('fairground',2,1,'Where would a family most likely buy a ticket for a carousel?','at the fairground entrance','in a silent reading room','at a farm’s irrigation ditch','旋转木马通常设在游乐场内。'),Q('fairground',3,1,'A fairground differs from a fair itself because it is the?','site where the fair is held','person who judges the contest','prize given to the winner','fairground 是活动地点，fair 是集市或游乐会。'),Q('fairground',4,1,'Which detail best establishes a fairground setting?','the smell of food stalls beside brightly lit rides','rows of reference books and library desks','a ship’s compass below deck','摊位和亮灯游乐设施是游乐场特征。')]);
P('fairy-tale','fairy-tale 由 fairy（仙子）与 tale（故事）组成；作形容词时常形容美好得近乎童话、或不太可信的情形。',C('fairy-tale.s1','比喻叙述','The couple’s fairy-tale romance seemed perfect in photographs, but they still had to work through ordinary disagreements about money and time.','这对情侣童话般的恋情在照片里看似完美，但他们仍须处理日常的金钱和时间分歧。','The couple’s fairy-tale romance seemed perfect in photographs / but they still had to work through ordinary disagreements / about money and time.','fairy-tale 作复合形容词修饰 romance；but 引出理想画面与现实琐事的对照。','romance 被描绘得仿佛童话般完美，正是比喻义。'),M('The fairy-tale report gave a verified list of routine train times and no magical or improbable details.','The timetable gave a verified list of routine train times and no magical or improbable details.','普通列车时刻表既不奇幻也不理想化，称 fairy-tale 不合适。'),[Q('fairy-tale',1,1,'A fairy-tale ending is often imagined as?','magically happy and almost too perfect','a routine account of office hours','a technical list of machine parts','fairy-tale 常形容童话式、近乎完美的结局。'),Q('fairy-tale',2,1,'Which claim sounds fairy-tale-like because it is improbable?','a lost ring returns after decades in a sealed letter','the train arrives two minutes late','the store opens at its posted time','失物多年后神奇归还显得难以置信。'),Q('fairy-tale',3,1,'In “a fairy-tale career,” the phrase most likely suggests?','an unusually fortunate, storybook-like success','a career studying folklore academically','a job that involves repairing clocks','此处比喻经历美好得像故事，而非研究童话。'),Q('fairy-tale',4,1,'Which is the best antonym in context for a fairy-tale promise?','a realistic promise','a magical promise','an improbable promise','realistic 与童话般、不切实际相对。')]);
P('faithfully','faithfully 由 faithful 加 -ly 构成；faithful 与 faith 同源，可表示忠诚，也可表示忠实于原物或原意。',C('faithfully.s1','艺术复原','The conservator faithfully reproduced the faded border from a high-resolution scan, matching its spacing without inventing missing decoration.','修复师依据高分辨率扫描忠实地复现了褪色边框，准确保留间距，没有臆造缺失的装饰。','The conservator faithfully reproduced the faded border / from a high-resolution scan / matching its spacing / without inventing missing decoration.','faithfully 修饰 reproduced；match details 表示尽量对应原件特征。','按扫描原样复制且不补造内容，体现忠实复现义。'),M('The translator faithfully changed the author’s claim into its opposite and added a new conclusion.','The translator accurately preserved the author’s claim and did not add a new conclusion.','把原意改成相反观点并添加结论不是忠实翻译。'),[Q('faithfully',1,1,'A copy made faithfully should?','preserve the original’s important details','replace the original with an unrelated design','omit details without telling the reader','faithfully 表示忠实地保留原物或原意。'),Q('faithfully',2,1,'A worker who serves faithfully is likely to?','remain loyal and dependable','break every promise deliberately','avoid the agreed responsibilities','忠诚可靠体现 faithfully 的忠诚义。'),Q('faithfully',3,1,'Which sentence uses faithfully to mean “accurately”?','The model faithfully reproduces the old bridge.','The guard faithfully deserted the post.','The sketch faithfully ignores the source.','准确复现旧桥是 faithful 的忠实复制用法。'),Q('faithfully',4,1,'A witness faithfully reports an event by?','stating what was seen without embellishment','adding an exciting detail that never happened','changing the order to blame someone','如实报告不添油加醋。')]);
P('faithfulness','faithfulness 由 faithful 加 -ness 构成，可指对人的忠诚，也可指对原始内容的准确遵守。',C('faithfulness.s1','翻译与承诺','The editor praised the translation’s faithfulness because it preserved the author’s argument and tone without copying the English word order awkwardly.','编辑赞扬译文忠实于原文，因为它保留了作者的论点和语气，又没有生硬照搬英文语序。','The editor praised the translation’s faithfulness / because it preserved the author’s argument and tone / without copying the English word order awkwardly.','faithfulness to a source 表示忠实于来源；preserve A without B 表示保持原意而非逐词照搬。','译文保持原文论点和语气，体现内容上的忠实。'),M('The translation showed faithfulness by reversing the author’s conclusion and deleting the evidence.','The translation showed unfaithfulness by reversing the author’s conclusion and deleting the evidence.','颠倒结论并删掉论据违背忠实原则，应称不忠实。'),[Q('faithfulness',1,1,'A translation’s faithfulness concerns how well it?','preserves the source meaning','adds claims the source rejects','copies only the title','faithfulness 可指译文忠于原文含义。'),Q('faithfulness',2,1,'In a relationship, faithfulness usually means?','loyalty and trustworthiness','frequent betrayal','forgetting every agreement','关系中的 faithfulness 指忠诚守信。'),Q('faithfulness',3,1,'What would demonstrate faithfulness to a promise?','doing what was agreed even when inconvenient','denying that the promise was made','quietly changing its terms','遵守约定体现忠实与守信。'),Q('faithfulness',4,1,'Which contrast best fits faithfulness in copying?','accuracy versus distortion','loyalty versus honesty','patience versus speed','复制语境中的忠实主要与歪曲相对。')]);
P('falconer','falconer 由 falcon（猎鹰）和施事者后缀 -er 构成，指饲养、训练并放飞猎鹰的人。',C('falconer.s1','传统猎鹰术','The falconer checked the bird’s leather jesses, then released it only after the rabbit had been flushed into open ground.','驯鹰人检查了猎鹰的皮脚带，等兔子被赶到开阔地后才放飞它。','The falconer checked the bird’s leather jesses / then released it / only after the rabbit had been flushed into open ground.','falconer 是管理猎鹰的人；release it 指放飞猎鹰，不是猎物。','检查猎鹰装备并放飞它参与狩猎，符合 falconer 的职业义。'),M('The falconer released the trained falcon but had never handled, fed, or trained a bird.','The spectator watched as someone else released the trained falcon.','从未饲养或训练鸟的人只是观众，不能据此称为 falconer。'),[Q('falconer',1,1,'A falconer works with?','falcons, training or flying them','fossils, cataloguing them','fences, painting them','falconer 指饲养或训练猎鹰的人。'),Q('falconer',2,1,'Which task best belongs to a falconer?','fitting a trained hawk with a jess before a flight','measuring a ship’s sails before launch','collecting eggs from a chicken incubator','安装猎鹰脚带并训练放飞属于驯鹰工作。'),Q('falconer',3,1,'A falconer differs from a casual birdwatcher because the falconer?','handles and trains birds of prey','only records distant sightings','studies plant roots','驯鹰人直接照料并训练猛禽。'),Q('falconer',4,1,'A falconer released the bird after?','checking its equipment and choosing a safe open area','locking it permanently inside an empty box','asking the rabbit to fly away','放飞前检查装备并选择合适地点，符合驯鹰活动。')]);
P('fallacious','fallacious 由 fallacy（谬误）加 -ous 构成；fallacy 经拉丁语 fallacia“欺骗、诡计”而来，指推理错误或误导性的。',C('fallacious.s1','论证评估','The claim that a medicine must work because it is expensive is fallacious; price alone provides no clinical evidence of effectiveness.','“药品价格高，所以一定有效”这一论断是谬误；价格本身并不能证明临床疗效。','The claim / that a medicine must work because it is expensive / is fallacious /; price alone provides no clinical evidence of effectiveness.','fallacious 修饰 claim；because 引出推理理由，分号后的说明揭示其逻辑缺陷。','单凭价格无法推出疗效，论证无效且会误导，符合该义。'),M('The conclusion was fallacious because each step followed from verified evidence without a logical gap.','The conclusion was sound because each step followed from verified evidence without a logical gap.','推理每步都由证据支持且无逻辑漏洞，与 fallacious 相反。'),[Q('fallacious',1,1,'A fallacious argument contains?','a misleading error in reasoning','a conclusion proved by every premise','a list of unrelated dates only','fallacious 指推理中有谬误、容易误导。'),Q('fallacious',2,1,'“Two famous people use it, so it cures everyone” is fallacious because it?','treats popularity as proof of a universal medical effect','reports the number of trial participants','compares two treatments in a controlled study','名人使用不能证明对所有人有效，推论站不住脚。'),Q('fallacious',3,1,'Which adjective most nearly contrasts with fallacious?','valid','deceptive','unsound','valid 表示有效、合乎逻辑。'),Q('fallacious',4,1,'A researcher identifies a fallacious inference by finding?','a conclusion that does not follow from the evidence','a source that reports the measured data','a calculation checked twice','结论不由证据推出时，推理存在谬误。')]);
P('fallible','fallible 来自拉丁语 fallibilis，与 fallere“欺骗、使出错”相关；表示人或判断有可能犯错，并非必然错误。',C('fallible.s2','证据判断','Even a carefully calibrated model is fallible, so the engineer checked its prediction against measurements from the new bridge.','即使经过仔细校准的模型也可能出错，因此工程师用新桥的实测数据核对其预测。','Even a carefully calibrated model is fallible / so the engineer checked its prediction / against measurements from the new bridge.','fallible 可修饰模型或判断；so 表示因其可能出错而核验的结果。','模型预测有出错可能，需实测核验，符合判断可能出错的义项。'),M('The witness was fallible, so every memory she reported was necessarily false.','The witness was fallible, so her memory was checked against other evidence.','fallible 表示可能犯错，不表示每次判断必然错误。'),[Q('fallible',1,1,'If a source is fallible, it?','can sometimes make mistakes','is guaranteed to be wrong every time','cannot ever be checked','fallible 表示可能出错，而非一定错。'),Q('fallible',2,2,'Why should an engineer recheck a fallible estimate?','it may be wrong despite careful work','it is certainly correct without evidence','it contains no numerical claim','估算可能有误，因此需要核验。'),Q('fallible',3,1,'Which statement correctly paraphrases “human judgement is fallible”?','people can make errors in their decisions','people always choose wrongly','people never use evidence','该句表示人的判断有时会犯错。'),Q('fallible',4,2,'A fallible test result should be treated as?','potentially mistaken and open to verification','proof that no further checking is possible','a fact that cannot change','可能有误意味着需要进一步验证。')]);
P('fallout','fallout 原指核爆后沉降的放射性尘埃，后由“落下物、余波”引申为争执、丑闻或决策带来的不良后果。',C('fallout.s1','组织决策','The budget dispute had political fallout: two senior members resigned, and the council postponed its vote until a new chair was chosen.','预算争议造成政治余波：两名高级成员辞职，委员会把表决推迟到选出新主席之后。','The budget dispute had political fallout / two senior members resigned / and the council postponed its vote / until a new chair was chosen.','fallout 可指事件造成的不良后果；冒号后列举辞职与延期。','辞职和表决延后是争议发生后的负面结果，符合 s1。'),M('The scandal had no fallout, so several officials resigned because nothing happened afterward.','The scandal had fallout, so several officials resigned as a consequence.','“无人受影响”与随后多人辞职自相矛盾；辞职显然是事件余波。'),[Q('fallout',1,1,'The fallout from a scandal means?','the consequences that follow it','the evidence collected before it','the plan that prevents it','fallout 比喻事件发生后的后果。'),Q('fallout',2,2,'After a nuclear blast, radioactive fallout consists of?','particles that settle back to the ground','fresh rainbows in the upper atmosphere','a warning siren installed underground','核爆 fallout 指放射性尘埃沉降物。'),Q('fallout',3,1,'Which is political fallout from a failed vote?','a minister resigns after the defeat','the ballot paper is printed beforehand','the debate begins before the vote','投票失败后官员辞职是后续负面结果。'),Q('fallout',4,1,'In “the fallout damaged relations,” fallout is closest to?','repercussions','preparations','celebrations','repercussions 是后果、影响。')]);
P('fallow','fallow 来自古英语 fealh，指暂不耕种、让土壤恢复的田地或状态，也可比喻未被使用的能力。',C('fallow.s1','轮作农业','The farmer left the northern field fallow for a season, giving its depleted soil time to recover before another crop was planted.','农场主让北边那块田休耕一季，让耗竭的土壤在种植下一茬作物前恢复。','The farmer left the northern field fallow for a season / giving its depleted soil time to recover / before another crop was planted.','leave a field fallow 表示暂不耕种；giving 分词说明休耕的目的或效果。','田地暂停种植以恢复地力，符合 s1。'),M('The farmer planted and harvested wheat continuously in the fallow field all season.','The farmer left the field uncultivated for a season so the soil could recover.','持续种植和收割不属于休耕；应说明土地暂时未耕作。'),[Q('fallow',1,1,'Land left fallow is?','not cultivated for a period','covered permanently by a city','being harvested every day','fallow 表示暂时不耕种的。'),Q('fallow',2,2,'A farmer may leave a field fallow to?','allow the soil to recover','make the field produce two crops at once','turn the field into a railway station','休耕常为恢复土壤地力。'),Q('fallow',3,3,'A fallow plot is best described as?','land temporarily unused for crops','a machine used to thresh grain','a crop ready for sale','fallow 作名词可指休耕地。'),Q('fallow',4,3,'“Her creative talent lay fallow” means her talent was?','unused despite its potential','destroyed beyond recovery','being displayed to an audience','比喻义表示有才能却暂未发挥。')]);
P('falsely','falsely 由 false 加副词后缀 -ly 构成；表示不真实地、错误地，或基于错误信念地作出判断。',C('falsely.s1','指控澄清','The article falsely claimed that the charity had spent all its donations on salaries, although audited accounts showed most funds went to clinics.','文章错误地声称慈善机构把所有捐款都用于薪酬，尽管审计账目显示大部分资金流向了诊所。','The article falsely claimed / that the charity had spent all its donations on salaries / although audited accounts showed / most funds went to clinics.','falsely 修饰 claimed，表示该声称不实；although 引出相反证据。','审计材料推翻了文章中的说法，证明其并非真实陈述。'),M('The article falsely reported the exact figure confirmed by three independent audits.','The article accurately reported the exact figure confirmed by three independent audits.','三份独立审计确认数字准确；称其 falsely report 与已核实事实冲突。'),[Q('falsely',1,1,'A person falsely accused of theft was accused?','without the accusation being true','after being convicted of theft','only after returning the stolen property','falsely 表示不实地、错误地。'),Q('falsely',2,1,'Which label was falsely applied to the package?','“fragile” on a steel beam that cannot be broken in normal shipping','“frozen” on ice cream kept below freezing','“urgent” on a same-day medical request','把易碎标签贴在坚固钢梁上明显不符合事实。'),Q('falsely',3,1,'If a graph falsely suggests growth, it?','misrepresents the data','shows the figures exactly as measured','lists sources without interpreting them','falsely suggests 表示图表错误地造成某种印象。'),Q('falsely',4,1,'The closest opposite of falsely in a verified report is?','accurately','mistakenly','dishonestly','accurately 表示准确地。')]);
P('faltering','faltering 是 falter 的现在分词形容词；falter 可能源于中古英语，表示脚步不稳、说话犹疑或进展开始衰退。',C('faltering.s1','比赛与表现','After a confident opening, the singer gave a faltering final verse, missing two notes as the orchestra carried on behind her.','开场自信之后，歌手最后一段唱得不稳，在乐队继续演奏时唱错了两个音。','After a confident opening / the singer gave a faltering final verse / missing two notes / as the orchestra carried on behind her.','faltering 修饰 verse，表示演唱开始不稳；missing 补充表现失误。','漏唱音符、演唱不稳，符合犹豫或不稳的含义。'),M('The faltering speaker delivered every sentence confidently, without a pause or mistake.','The assured speaker delivered every sentence confidently, without a pause or mistake.','全程自信流畅的演讲并不 faltering；assured 更贴切。'),[Q('faltering',1,1,'A faltering voice sounds?','uncertain or unsteady','perfectly firm and uninterrupted','silent because no one is speaking','faltering 表示声音或表现不稳定、犹疑。'),Q('faltering',2,1,'A faltering economy is one that is?','beginning to weaken or lose momentum','growing rapidly without interruption','unrelated to financial activity','经济开始衰退或失去动力可称 faltering。'),Q('faltering',3,1,'Which action is faltering?','a runner loses rhythm and stumbles near the finish','a runner keeps the same pace throughout','a runner watches the race from a seat','步伐变乱、临近终点绊倒体现 faltering。'),Q('faltering',4,1,'A faltering reply may include?','hesitations that show uncertainty','an immediate and clear answer','a written receipt with no response','回答犹豫不决体现 faltering。')]);
P('familiarization','familiarization 由 familiarize 加名词后缀 -ation 构成；familiarize 与 familiar 同源，表示学习环境、系统或任务的基本情况而熟悉起来。',C('familiarization.s1','新员工培训','The first hour is for familiarization with the lab’s evacuation routes, equipment labels, and sign-in procedure; practical work begins afterward.','第一小时用于熟悉实验室的疏散路线、设备标签和签到流程，之后才开始实际操作。','The first hour is for familiarization with the lab’s evacuation routes, equipment labels, and sign-in procedure / practical work begins afterward.','familiarization with + 对象；with 后列出需要了解的场所信息和流程。','培训先帮助新人了解环境和程序，符合“熟悉”的名词义。'),M('The familiarization session deliberately hid the equipment guide and prevented new staff from learning the room layout.','The orientation session introduced the equipment guide and room layout to new staff.','阻止新人了解环境与 familiarization（熟悉化）目的相反。'),[Q('familiarization',1,1,'A familiarization tour is intended to help someone?','learn the basic layout and procedures','forget where the exits are','take a final examination','familiarization 让人熟悉环境或流程。'),Q('familiarization',2,1,'Before using unfamiliar software, familiarization may include?','trying its main controls with a guide','deleting every help page','guessing a password without instruction','通过指导了解软件主要操作属于熟悉过程。'),Q('familiarization',3,1,'Which phrase is natural?','familiarization with the safety rules','familiarization at the safety rules','familiarization by the safety rules','familiarization 常与 with 连用。'),Q('familiarization',4,1,'Familiarization differs from certification because familiarization?','introduces a person to something without necessarily proving mastery','always awards a professional license','requires no contact with the subject','熟悉化是了解入门，不等于证明专业资格。')]);
P('famish','famish 与 famished 同源，通常表示使某人极度挨饿，也可作不及物动词表示自己挨饿；现代常见替代说法是 starve。',C('famish.s2','求生与补给','The stranded hikers began to famish after their food ran out, so the rescue team dropped water and high-energy bars near the marked ridge.','食物耗尽后，受困的徒步者开始挨饿，救援队于是把水和高能量棒投放到标记过的山脊附近。','The stranded hikers began to famish / after their food ran out / so the rescue team dropped water and high-energy bars / near the marked ridge.','不及物 famish 表示遭受饥饿；after 引出食物耗尽的原因。','食物耗尽后徒步者因饥饿受苦，符合 s2。'),M('The hikers famished the campsite by feeding everyone a large dinner.','The hikers fed everyone a large dinner at the campsite.','吃饱与受饥饿矛盾；famish 是使挨饿或挨饿，不是喂饱。'),[Q('famish',1,2,'If people famish during a long siege, they?','suffer greatly from lack of food','eat more than they can comfortably manage','build shelters against the rain','不及物 famish 指遭受严重饥饿。'),Q('famish',2,1,'A cruel ruler may famish prisoners by?','withholding their food','bringing them regular meals','teaching them to cook','及物 famish 表示使人挨饿。'),Q('famish',3,2,'Which sentence uses famish intransitively?','Without supplies, the crew began to famish.','The guards famished the crew deliberately.','The cook famished the stew with herbs.','began to famish 无宾语，表示船员自己挨饿。'),Q('famish',4,1,'In “war can famish a population,” famish means?','make people go hungry','help people find shelter','teach people to grow crops','及物 famish 是使人陷入饥饿。')]);
P('fanatic','fanatic 经法语来自拉丁语 fanaticus，早期指受神庙或神灵启示的人；现代名词指信念过度狂热者，也可指体育或爱好迷。',C('fanatic.s3','体育爱好','As a cycling fanatic, Nora knows the route profiles by heart and plans her holidays around the mountain stages of major races.','作为自行车迷，诺拉熟记各条赛道的起伏，并围绕大型赛事的山地赛段安排假期。','As a cycling fanatic / Nora knows the route profiles by heart / and plans her holidays / around the mountain stages of major races.','fanatic of/about a hobby 表示极度热衷者；as 引出身份。','她围绕自行车赛事安排生活，体现爱好者义 s3。'),M('The fanatic barely cared about cycling and could not name a single race.','The casual observer barely cared about cycling and could not name a single race.','对运动毫不在意的人不是 fanatic；casual observer 才符合。'),[Q('fanatic',1,3,'A chess fanatic is likely to?','spend much of their free time studying games','avoid learning the rules','confuse a chessboard with a cooking pot','fanatic 可指对爱好极其投入的人。'),Q('fanatic',2,1,'A political fanatic may be dangerous when the person?','supports an idea without questioning extreme actions','compares policies carefully using evidence','changes an opinion after new evidence','信念狂热且不加反思可能支持极端行动。'),Q('fanatic',3,3,'Which person best fits “a film fanatic”?','someone who collects reviews and watches films every week','someone who has never seen a movie','someone who repairs a cinema roof once','持续投入观影与研究的爱好者是 fanatic。'),Q('fanatic',4,2,'As an adjective, fanatic support is?','extreme and uncritical','mild and occasional','unrelated to the cause','fanatic 作形容词表示狂热、盲目的。')]);
P('fanatical','fanatical 由 fanatic 加形容词后缀 -al 构成，表示热情或信念过度强烈，常暗含不够理性或超出适度。',C('fanatical.s1','组织行为','The coach’s fanatical demand for daily practice left no time for rest, and several players developed injuries before the season began.','教练狂热地要求每天训练，完全不给休息时间，赛季开始前已有几名队员受伤。','The coach’s fanatical demand for daily practice / left no time for rest / and several players developed injuries / before the season began.','fanatical 修饰 demand，强调热情过度；后半句说明不合理的后果。','训练要求超越合理限度并造成伤害，体现 excessive zeal。'),M('The coach took a measured approach, scheduling short practices and ample rest; this was fanatical training.','The coach took a measured approach, scheduling short practices and ample rest; this was balanced training.','适度训练并安排充分休息不是过度狂热。'),[Q('fanatical',1,1,'Fanatical devotion is usually?','excessive and difficult to question','mild and easily set aside','based on no particular interest','fanatical 暗含过度热衷、缺乏理性。'),Q('fanatical',2,1,'Which behavior is fanatical?','refusing all medical advice to keep training every day','following a doctor’s plan with rest days','enjoying a sport twice a month','无视医疗建议、每天强迫训练超出合理程度。'),Q('fanatical',3,1,'Choose the most suitable noun after fanatical.','loyalty to a cause','occasional curiosity','neutral temperature','fanatical 常修饰 loyalty、support 等，表示狂热。'),Q('fanatical',4,1,'A fanatical argument may ignore?','reasonable objections and evidence','all emotional language','the topic under discussion entirely','盲目狂热可能不理会合理反对意见与证据。')]);
P('fanciful','fanciful 由 fancy 加 -ful 构成，fancy 与古法语 fantasie、希腊语 phantasia（想象）有关；可指富于奇想，也可指脱离现实的。',C('fanciful.s1','方案评审','The architect rejected the fanciful proposal for a glass tower beneath the lake because no engineering study showed how it could withstand the pressure.','建筑师否决了在湖底建玻璃塔的异想天开方案，因为没有工程研究证明它能承受水压。','The architect rejected the fanciful proposal / for a glass tower beneath the lake / because no engineering study showed / how it could withstand the pressure.','fanciful 修饰方案，表示想象丰富但不现实；because 引出可行性缺失。','湖底玻璃塔没有工程依据，想法不切实际，符合义项。'),M('The fanciful plan was already supported by tested materials, a funded design, and a successful full-scale trial.','The practical plan was already supported by tested materials, a funded design, and a successful full-scale trial.','材料、资金和实测都支持方案时，称其 fanciful 不合适。'),[Q('fanciful',1,1,'A fanciful explanation is often?','imaginative but not realistic','a plain record of verified measurements','a rule required by every court','fanciful 可指想象丰富但不现实。'),Q('fanciful',2,1,'Which invention sounds fanciful without evidence?','a bicycle that crosses oceans by floating on moonlight','a battery-powered lamp','a rain gauge placed outdoors','靠月光浮海的自行车设想缺乏现实基础。'),Q('fanciful',3,1,'A fanciful costume might look?','elaborately whimsical, like something from a dream','plain and identical to a standard uniform','damaged by ordinary wear','该词也可强调奇异、想象性强的外观。'),Q('fanciful',4,1,'The closest opposite of a fanciful forecast is a?','realistic forecast','whimsical forecast','improbable forecast','realistic 与脱离实际的 fanciful 相对。')]);
P('fanner','fanner 由 fan 加施事者后缀 -er 构成，可指扇风的人或机器中使空气流动的部件。',C('fanner.s1','机械通风','The small fanner inside the projector kept air moving across the lamp, preventing the casing from overheating during the long screening.','投影机里的小风扇让空气流过灯泡，避免机壳在长时间放映时过热。','The small fanner inside the projector / kept air moving across the lamp / preventing the casing from overheating / during the long screening.','fanner 可指送风部件；keep air moving 表明其通风作用。','投影机内部部件推动空气流动、帮助散热，符合机器部件义。'),M('The fanner stopped all air movement and made the projector hotter by forcing hot air back onto the lamp.','The blocked vent stopped all air movement and made the projector hotter.','使空气流动的 fanner 不等于堵住气流的 vent。'),[Q('fanner',1,1,'A machine’s fanner is a part that?','moves air','measures distance','stores water','fanner 可指使空气流动的机器部件。'),Q('fanner',2,1,'Why might a projector contain a fanner?','to carry heat away from its lamp','to print captions on the screen','to measure the film’s length','风扇帮助灯泡散热。'),Q('fanner',3,1,'A person fanning a fire is acting as a?','fanner','fender','farmer','fanner 也可指扇风的人。'),Q('fanner',4,1,'Which statement about a fanner is correct?','it may be a person or an air-moving device','it always names a type of mineral','it means a wall that blocks every breeze','词条兼有人与机器部件两种义项。')]);
P('fantasize','fantasize 由 fantasy 加动词后缀 -ize 构成；fantasy 经古法语来自希腊语 phantasia“想象”，表示沉浸于想象的情景。',C('fantasize.s1','职业规划','During the long commute, Mei sometimes fantasizes about opening a tiny bookshop by the sea, though she knows the idea would require careful planning.','长途通勤时，梅有时会幻想在海边开一家小书店，尽管她知道这个想法还需要周密规划。','During the long commute / Mei sometimes fantasizes about opening a tiny bookshop by the sea / though she knows the idea / would require careful planning.','fantasize about + 名词或动名词；though 从句显示这是设想而非已落实计划。','她在脑海中想象理想职业场景，符合该动词义。'),M('Mei fantasized a signed lease and opening day into reality without ever making the plan.','Mei imagined the shop but still needed to plan, sign a lease, and prepare for opening day.','单靠幻想不会自动把想法变成现实。'),[Q('fantasize',1,1,'To fantasize about a journey is to?','imagine taking it, perhaps without making real plans','purchase every ticket immediately','report the trip after it ends','fantasize 指想象某种情景。'),Q('fantasize',2,1,'Which sentence uses fantasize naturally?','He fantasized about winning the race while sitting on the bus.','He fantasized the bus into the station by repairing its brakes.','He fantasized at the ticket in his pocket.','fantasize about + 情景表达心中想象。'),Q('fantasize',3,1,'A person fantasizing about fame may be?','imagining what it would be like to become famous','checking the official population count','writing down a verified biography','幻想成名属于对愿望情景的想象。'),Q('fantasize',4,1,'Which contrast best separates fantasizing from acting?','imagining a plan versus carrying it out','reading a plan versus losing it','remembering a past event versus forgetting it','幻想是想象，行动则是实际执行。')]);
P('fantastical','fantastical 由 fantastic 加 -al 构成，fantastic 最终与 fantasy 同源；形容极富想象、奇异得不似现实的事物。',C('fantastical.s1','舞台布景','The opera’s fantastical set placed a silver forest above the orchestra, with oversized moons and stairways that appeared to float.','歌剧的奇幻布景把银色森林置于乐池上方，巨大的月亮和仿佛漂浮的楼梯点缀其间。','The opera’s fantastical set placed a silver forest above the orchestra / with oversized moons and stairways / that appeared to float.','fantastical 修饰舞台布景；后续意象说明其超现实、奇异特征。','漂浮楼梯与巨型月亮构成奇异想象世界，符合 fantastical。'),M('The fantastical report listed ordinary dates and measured rainfall without any unusual or imagined details.','The factual report listed ordinary dates and measured rainfall without any unusual or imagined details.','如实记录日期与雨量的报告没有幻想内容，应称 factual。'),[Q('fantastical',1,1,'A fantastical landscape is likely to be?','strange and richly imaginative','an exact map with no artistic additions','a level field measured by surveyors','fantastical 表示奇异、充满想象。'),Q('fantastical',2,1,'Which design is fantastical?','a staircase that curls through a cloud into a moonlit palace','a standard fire exit beside a door','a map that marks roads to scale','云中通向月宫的楼梯是奇幻设计。'),Q('fantastical',3,1,'In a fantastical story, animals might?','speak and build a city in the sky','remain ordinary animals in a farm report','appear only as numerical data','奇幻故事可让动物说话并建造天空城市。'),Q('fantastical',4,1,'Choose the closest contrast to fantastical in a news report.','ordinary and factual','bizarre and imaginary','magical and dreamlike','factual、ordinary 与奇幻虚构相对。')]);
P('fanwise','fanwise 由 fan（扇子）和 -wise（以……方式/方向）构成，描述物体像展开的扇骨那样从一点向外散开。',C('fanwise.s1','建筑构件','The roof beams spread fanwise from the central column, creating a wide canopy without placing a support post at every edge.','屋顶梁从中央柱子向外呈扇形展开，形成宽阔的顶棚，而不必在每条边缘都立支柱。','The roof beams spread fanwise from the central column / creating a wide canopy / without placing a support post at every edge.','fanwise 作副词修饰 spread；from 引出扇形展开的起点。','梁从一个中心点向外张开，形状如展开的扇子。'),M('The ribs lay fanwise in one straight parallel line with no point from which they spread.','The ribs lay parallel in one straight line with no point from which they spread.','直线平行排列不呈扇形张开，不能称 fanwise。'),[Q('fanwise',1,1,'Branches arranged fanwise spread?','outward from a common point','in a single closed ring only','randomly without any outward pattern','fanwise 描述从一点向外呈扇形排列。'),Q('fanwise',2,1,'Which arrangement is fanwise?','rays opening from one hinge like a hand fan','parallel rails running side by side','stones piled in a compact heap','围绕铰点展开的扇骨是典型 fanwise 排列。'),Q('fanwise',3,1,'The word fanwise describes mainly?','the direction or pattern of spreading','the material’s chemical composition','the number of people in a room','后缀 -wise 表示方式或方向。'),Q('fanwise',4,1,'A fanwise pattern would be useful for?','roof supports radiating from one central post','a row of identical windows along one wall','a stack of books placed one above another','从中央支点放射展开的屋梁适合 fanwise。')]);
P('far-fetched','far-fetched 由 far 与 fetch 构成，字面有“牵扯得很远”之意；惯用形容推测、解释或故事牵强而难以令人相信。',C('far-fetched.s1','推理审查','The detective called the theory far-fetched because it required a stranger to cross three locked rooms unseen and leave no trace.','侦探称这个理论牵强，因为它要求一个陌生人不留痕迹地穿过三间上锁的房间。','The detective called the theory far-fetched / because it required a stranger / to cross three locked rooms unseen / and leave no trace.','call A far-fetched 表示认为 A 牵强；because 说明难以置信的前提。','解释依赖一连串难以成立的条件，符合 far-fetched。'),M('The explanation was far-fetched because it followed directly from video evidence and required no unusual assumptions.','The explanation was well supported because it followed directly from video evidence and required no unusual assumptions.','直接受到录像证据支持、没有异常假设的解释并不牵强。'),[Q('far-fetched',1,1,'A far-fetched excuse is?','difficult to believe because it seems unlikely','plainly supported by a signed record','short enough to fit on one line','far-fetched 表示牵强、不大可信。'),Q('far-fetched',2,1,'Which explanation sounds far-fetched?','a cat secretly operated a city subway for a year','a train was delayed by a broken signal','a package arrived one day late','猫秘密驾驶地铁一年极不可信。'),Q('far-fetched',3,1,'If a reviewer says a plot twist is far-fetched, the reviewer finds it?','implausible','carefully foreshadowed and believable','historically verified','far-fetched 与可信、合理相反。'),Q('far-fetched',4,1,'A claim becomes less far-fetched when it is?','supported by independent evidence','based on an increasingly unlikely chain','repeated without any source','独立证据能提高可信度。')]);
P('faraway','faraway 由 far（远）与 away（离开、远处）组合而成，可描述空间距离远，也可形容心神恍惚、仿佛想着别处。',C('faraway.s2','注意力状态','When the lecturer asked for her view, the faraway student blinked and requested the last question again, having been lost in thought.','讲师询问她的看法时，心不在焉的学生眨了眨眼，请对方再说一遍最后的问题，因为她刚才走神了。','When the lecturer asked for her view / the faraway student blinked and requested the last question again / having been lost in thought.','faraway 修饰 student，描述出神状态；having been lost 补充走神的原因。','她沉浸于自己的思绪而没有听清提问，符合 s2。'),M('He gave a faraway answer that addressed every detail of the question immediately and attentively.','He gave a focused answer that addressed every detail of the question immediately and attentively.','专注并即时回应不体现恍惚、心不在焉。'),[Q('faraway',1,2,'A faraway expression may suggest that a person is?','lost in thought','angry about a nearby noise','carefully watching every speaker','s2 比喻神情恍惚、心思在别处。'),Q('faraway',2,1,'A faraway island is?','a long distance from the speaker','directly beside the harbor','invisible because it is imaginary','faraway 的空间义表示距离遥远。'),Q('faraway',3,2,'Which detail shows a faraway look rather than a distant location?','she stared past the screen and missed her name','the village lies 600 miles away','the island appears beyond the horizon','走神错过自己的名字体现 s2。'),Q('faraway',4,1,'“They heard a faraway bell” means the bell sounded?','from a distant place','inside the listener’s pocket','only in a dream','faraway 修饰声音可表示来自远处。')]);
P('farmhand','farmhand 由 farm（农场）和 hand（工人）组成，指受雇在农场做体力劳动的人。',C('farmhand.s1','季节性用工','The farmhand repaired a broken irrigation hose before moving the harvested crates into the cool storage shed.','农场工人修好破裂的灌溉软管，然后把收获的箱子搬进冷藏棚。','The farmhand repaired a broken irrigation hose / before moving the harvested crates / into the cool storage shed.','farmhand 指农场体力劳动者；repair 与 move 是具体农活。','修灌溉管并搬运收获物是农场雇工的工作。'),M('The farmhand spent the entire year issuing court judgments and never worked on a farm.','The judge spent the entire year issuing court judgments and never worked on a farm.','审判工作不属于农场雇工的职责。'),[Q('farmhand',1,1,'A farmhand is paid mainly to?','do manual work on a farm','design computer processors','inspect court cases','farmhand 指农场雇工。'),Q('farmhand',2,1,'Which task would a farmhand most likely perform?','mend a fence around a pasture','approve a city building law','translate a ship’s navigation chart','修理牧场围栏是农场劳动。'),Q('farmhand',3,1,'A farmhand differs from the farm owner in that the farmhand is often?','an employee doing practical tasks','the person who owns every neighboring field','a machine that waters crops','farmhand 是农场雇员，不一定是所有者。'),Q('farmhand',4,1,'The farmhand loaded produce before?','driving it to the market','conducting a court appeal','launching a satellite','把农产品运去市场是常见农场工作。')]);
P('farmland','farmland 由 farm 与 land 合成，指用于耕种或畜牧的农业土地，与城镇、荒漠等土地用途相对。',C('farmland.s1','土地用途','The new railway would cross several acres of farmland, so planners met with growers to limit damage to crops and irrigation channels.','新铁路将穿过数英亩农田，因此规划人员与种植者会面，以减少对作物和灌溉渠的破坏。','The new railway would cross several acres of farmland / so planners met with growers / to limit damage to crops and irrigation channels.','farmland 常作不可数集合名词；acres of 表面积，后文列出农业用途受影响之处。','被作物和灌渠占用的土地属于 farmland。'),M('The city classified its crowded downtown shopping blocks as farmland although no crops or livestock were kept there.','The city classified its crowded downtown shopping blocks as commercial land.','市中心商业街区不用于农业生产，称 farmland 不准确。'),[Q('farmland',1,1,'Farmland is land primarily used for?','growing crops or raising livestock','building dense office towers','storing ocean-going ships','farmland 指农业用地。'),Q('farmland',2,1,'Which change converts farmland to another use?','paving the field for a shopping complex','planting barley in the field','rotating crops between the plots','铺成购物中心后不再是农田用途。'),Q('farmland',3,1,'A map labels a region “farmland.” It likely shows?','fields and agricultural holdings','only apartment blocks and subway lines','a deep-water port','农田地图应显示田地和农业地块。'),Q('farmland',4,1,'“Acres of farmland” measures?','an area used for agriculture','a number of farm workers','a shipment of fertilizer','acres 度量土地面积。')]);
P('farsighted','farsighted 由 far 与 sighted 构成，有两义：能预见长期影响、有远见；或眼睛看远处清楚、看近处费力的远视。',C('farsighted.s1','公共政策','The farsighted mayor invested in flood barriers years before the risk became urgent, saving the city from emergency construction after the river rose.','这位有远见的市长在洪水风险变得紧迫多年之前就投资修建防洪设施，使城市免于河水上涨后的紧急施工。','The farsighted mayor invested in flood barriers years before the risk became urgent / saving the city / from emergency construction after the river rose.','farsighted 在此指预先考虑长期后果；years before 点明提前决策。','提前应对尚未紧迫的未来风险体现 s1 的远见。'),M('The farsighted plan ignored every long-term risk and focused only on tomorrow’s minor convenience.','The short-sighted plan ignored every long-term risk and focused only on tomorrow’s minor convenience.','只顾眼前而无视长期风险属于 short-sighted。'),[Q('farsighted',1,1,'A farsighted decision-maker considers?','how choices today affect the future','only the next five minutes','whether an object is close to the eye','farsighted 的比喻义指有远见。'),Q('farsighted',2,2,'A farsighted reader may need glasses because nearby print is?','harder to see clearly than distant objects','clear while distant signs are blurry','visible only in total darkness','医学义指远视：近处较难看清。'),Q('farsighted',3,1,'Which investment is farsighted in the planning sense?','repairing a seawall before rising tides threaten homes','spending the entire safety budget on a one-day party','ignoring maintenance until a bridge collapses','提前投资防护设施考虑了长期后果。'),Q('farsighted',4,2,'A person who sees distant signs clearly but struggles with a nearby book may be?','farsighted','near-sighted','color-blind','描述与医学远视的典型情况一致。')]);
P('fascinated','fascinated 是 fascinate 的过去分词形容词；fascinate 经法语与拉丁语 fascinare“施魔法、迷住”而来，表示被深深吸引。',C('fascinated.s1','自然观察','The children were fascinated by the ant colony, watching workers carry crumbs underground and signal to one another along the trail.','孩子们被蚁群深深吸引，看着工蚁把面包屑搬进地下，并沿着路线彼此传递信号。','The children were fascinated by the ant colony / watching workers carry crumbs underground / and signal to one another along the trail.','be fascinated by + 吸引人的对象；watching 说明兴趣表现。','孩子持续专注观察蚂蚁活动，说明他们着迷。'),M('The children were fascinated by the exhibit, so they ignored it and left before looking.','The children were bored by the exhibit, so they ignored it and left before looking.','对展览着迷与完全不看就离开不相符，bored 表示无聊更合理。'),[Q('fascinated',1,1,'A fascinated audience is?','deeply interested and absorbed','unable to hear anything at all','angry because it missed a bus','fascinated 表示深受吸引、很感兴趣。'),Q('fascinated',2,1,'Which reaction shows someone is fascinated by a machine?','they keep studying how its gears move','they turn away and refuse to look','they ask for the room’s exit immediately','持续研究机械运转说明被吸引。'),Q('fascinated',3,1,'Complete the natural pattern: “She was fascinated ___ the fossil.”','by','from','at to','常用 be fascinated by。'),Q('fascinated',4,1,'A fascinated child may?','ask many questions about the discovery','lose all interest before seeing it','hide the object without examining it','好奇并不断提问体现着迷状态。')]);
P('fascinating','fascinating 是 fascinate 的现在分词形容词，描述引人入胜、令读者或观众持续关注的事物。',C('fascinating.s2','科普写作','The guide made the migration routes fascinating by showing how tiny changes in wind can redirect thousands of birds across a continent.','导览员讲解了微小风向变化如何让数千只鸟横越大陆改道，使迁徙路线变得引人入胜。','The guide made the migration routes fascinating / by showing how tiny changes in wind / can redirect thousands of birds / across a continent.','make + 宾语 + fascinating；by showing 说明引人入胜的讲解方式。','令人意外的迁徙机制吸引注意，符合 s2。'),M('The fascinating lecture held nobody’s attention and every listener fell asleep immediately.','The dull lecture held nobody’s attention and every listener fell asleep immediately.','无人感兴趣、听众睡着与“引人入胜”矛盾。'),[Q('fascinating',1,2,'A fascinating explanation is one that?','holds attention and makes people want to learn more','contains no information about its subject','is impossible to hear','fascinating 指引人入胜、吸引注意。'),Q('fascinating',2,1,'A fascinating museum display may?','make visitors pause to examine its details','leave every visitor indifferent','consist only of a locked empty case','让访客停下来观察说明展览吸引人。'),Q('fascinating',3,2,'Which talk is most likely fascinating?','a clear account of how a glacier shaped the valley','a speaker reading an unrelated phone list','a silent room with no presentation','生动解释冰川塑造山谷的过程更能引起兴趣。'),Q('fascinating',4,1,'Choose the natural phrase.','a fascinating account of the expedition','a fascinated account that attracts readers','a fascination accounting the expedition','fascinating 修饰吸引读者的叙述。')]);
P('fascination','fascination 是 fascinate 加 -ation 构成的名词，可指吸引力、着迷状态或令人着迷的事物。',C('fascination.s2','长期兴趣','Her fascination with deep-sea life began after she watched a documentary and later joined a research team to catalogue unusual marine organisms.','她对深海生物的着迷始于一部纪录片，后来她加入研究团队，参与编目奇特的海洋生物。','Her fascination with deep-sea life began after she watched a documentary / and later joined a research team / to catalogue unusual marine organisms.','fascination with + 对象表示对某事物的强烈兴趣；began 和 later 描述兴趣发展。','她持续投入深海生物研究，体现着迷状态 s2。'),M('His fascination with astronomy meant he never looked at the stars and refused to learn their names.','His indifference to astronomy meant he never looked at the stars and refused to learn their names.','拒绝观察、毫无兴趣与 fascination 相反。'),[Q('fascination',1,2,'A fascination with astronomy is?','a strong and sustained interest in the subject','a brief inability to see stars','a method for measuring telescope weight','fascination 可指持续强烈的兴趣。'),Q('fascination',2,1,'The old clock has a fascination for visitors because it?','attracts their attention and curiosity','is hidden in a locked room','was discarded as useless','名词可表示具有吸引人的魅力。'),Q('fascination',3,3,'Which is an example of a fascination as “a thing”?','an abandoned palace that draws curious explorers','the feeling of being bored in a queue','a tool used to fasten two boards','此处指吸引人的事物。'),Q('fascination',4,2,'In “the fascination of the subject,” fascination most nearly means?','its power to attract interest','the subject’s verified price','the subject’s legal ownership','of 引出的结构可指事物本身的吸引力 s1。')]);
P('fatalism','fatalism 经法语源自拉丁语 fatalis“命运注定的”，指相信事情由命运决定、个人行动无法改变结果的观点。',C('fatalism.s1','风险应对','Her fatalism made her dismiss the evacuation warning as pointless, even though moving uphill could have reduced her family’s danger.','她的宿命论使她认为撤离警报毫无意义，尽管搬到高处本可降低家人的危险。','Her fatalism made her dismiss the evacuation warning as pointless / even though moving uphill / could have reduced her family’s danger.','fatalism 作名词表示对宿命的信念；even though 引出行动可能改变风险的反证。','认为努力无法改变结果而拒绝采取行动，体现宿命论。'),M('Fatalism means believing that careful actions can always change every outcome, regardless of chance.','Fatalism means believing that fate determines outcomes despite people’s efforts.','相信行动总能改变结果与宿命决定论相反。'),[Q('fatalism',1,1,'Fatalism is the belief that?','fate determines events and effort cannot alter them','every event is chosen freely by each person','chance has no role in anyone’s life','fatalism 认为命运主宰结果，人的努力难以改变。'),Q('fatalism',2,1,'A fatalistic response to a preventable risk might be?','“There is no point preparing; whatever happens is fixed.”','“Let’s check the warning and reduce the danger.”','“We should compare the available safety plans.”','认为准备无用、结果注定属于宿命论态度。'),Q('fatalism',3,1,'Which view contrasts most with fatalism?','people can influence some outcomes through their choices','destiny settles every important event','effort is always pointless','行动能影响结果与宿命论相对。'),Q('fatalism',4,1,'A novel about fatalism would likely explore?','characters who feel powerless before destiny','a recipe with exact cooking times','a map of local bus stops only','宿命论文学关注人物面对命运的无力感。')]);
P('fateful','fateful 由 fate（命运）加 -ful 构成，可指对未来影响重大的决定性时刻，也可带有仿佛命运安排的意味。',C('fateful.s1','历史决策','The fateful vote committed the country to a costly campaign that shaped public debate for decades.','这场具有决定性影响的投票使国家投入一场代价高昂的行动，并在数十年间塑造了公共辩论。','The fateful vote committed the country to a costly campaign / that shaped public debate / for decades.','fateful 修饰 vote，强调其长期、重大的影响；that 从句说明后果。','投票改变国家道路并长期影响讨论，符合 s1。'),M('The fateful choice had no lasting effect and was forgotten before the meeting ended.','The routine choice had no lasting effect and was forgotten before the meeting ended.','毫无持久影响的普通选择不具决定性，不宜称 fateful。'),[Q('fateful',1,1,'A fateful decision is one that?','has important and lasting consequences','is made at exactly noon','cannot be written down','fateful 表示会显著影响未来的。'),Q('fateful',2,2,'A character calls a meeting fateful because it seems?','guided by destiny and impossible to avoid','unrelated to the story’s future','a routine lunch appointment','s2 带有命运安排、不可避免的意味。'),Q('fateful',3,1,'Which event is most likely fateful?','a treaty that changes borders for generations','a clerk changing one sheet of stationery','a bus stopping at its regular station','影响几代人的条约具有长期重大后果。'),Q('fateful',4,1,'In “a fateful encounter,” the adjective hints at?','an encounter with major future consequences','a meeting that has no effect at all','a meeting that lasts only five minutes','fateful encounter 暗示相遇会重大地改变未来。')]);
P('fatigued','fatigued 是 fatigue 的过去分词形容词；fatigue 经法语与拉丁语 fatigare“使疲惫”而来，描述因劳累、疾病或长期压力而疲乏。',C('fatigued.s1','工作与休息','The fatigued rescue crew rotated shifts after carrying supplies uphill all night, reducing the risk of mistakes during the final search.','救援队整夜把物资搬上山后已十分疲惫，于是轮班休息，以降低最后搜寻时出错的风险。','The fatigued rescue crew rotated shifts / after carrying supplies uphill all night / reducing the risk of mistakes / during the final search.','fatigued 描述持续努力后的状态；after + 动名词指出疲劳来源。','整夜搬运后需要轮休，体现劳累导致的疲乏。'),M('The fatigued crew had slept well, rested all day, and felt fully alert throughout the night shift.','The rested crew had slept well, rested all day, and felt fully alert throughout the night shift.','充分休息且精力充沛与疲乏状态不一致。'),[Q('fatigued',1,1,'A fatigued worker is?','very tired after effort or strain','unable to feel any emotion','newly trained for a task','fatigued 表示疲劳、疲乏。'),Q('fatigued',2,1,'Which situation could leave a climber fatigued?','ascending steep trails for many hours','sitting comfortably for two minutes','reading a short label at home','长时间攀登会造成疲劳。'),Q('fatigued',3,1,'A fatigued driver should?','stop and rest before continuing','increase speed to finish sooner','ignore every sign of drowsiness','疲劳驾驶应停止休息以保障安全。'),Q('fatigued',4,1,'Which is the best contrast for a fatigued athlete?','a rested athlete','an exhausted athlete','a weary athlete','rested 与疲惫状态相反。')]);
P('fatten','fatten 由 fat 加动词后缀 -en 构成，表示喂养动物使其增重，也可泛指使某物脂肪增加。',C('fatten.s1','畜牧饲养','The farmer adjusted the feed to fatten the lambs gradually, monitoring their health rather than trying to force rapid weight gain.','农场主调整饲料，让羊羔逐渐增重，同时监测它们的健康，而不是强行快速催肥。','The farmer adjusted the feed to fatten the lambs gradually / monitoring their health / rather than trying to force rapid weight gain.','fatten + 宾语表示使某物增肥；to fatten 表示调整饲料的目的。','通过饲养使羔羊增重，符合 fatten 的使动义。'),M('The farmer fattened the lambs by withholding all food until they lost weight.','The farmer fattened the lambs by providing suitable feed so they gained weight.','断食导致减重，与 fatten（使增肥）结果相反。'),[Q('fatten',1,1,'To fatten livestock is to?','feed it so that it gains weight','train it to run faster','remove all its food','fatten 作动词表示喂养增重。'),Q('fatten',2,1,'Which action would fatten a young animal?','providing a suitable high-energy diet','withholding food for several days','moving it to a colder empty stall','适宜高能饲料帮助动物增重。'),Q('fatten',3,1,'In “fatten the budget with extra fees,” fatten is used figuratively to mean?','increase its size','reduce it sharply','copy it exactly','比喻中 fatten 表示使数量或规模增加。'),Q('fatten',4,1,'Choose the natural phrase.','fatten a calf for market','fatten a calendar to read it','fatten a fence to stop rain','fatten 的常见宾语可为待出售的牲畜。')]);
P('fatty','fatty 由 fat 加 -y 构成形容词，表示含脂肪比例高；具体食品营养含量应以标签或可靠测量为准。',C('fatty.s1','食品成分','The nutrition label showed that the fatty cut of pork contained more saturated fat per serving than the lean alternative.','营养标签显示，这块脂肪较多的猪肉每份饱和脂肪含量高于瘦肉。','The nutrition label showed / that the fatty cut of pork contained more saturated fat per serving / than the lean alternative.','fatty 修饰 cut，说明脂肪比例较高；比较结果由 than 引出。','标签所示脂肪含量较高，符合 fatty 的“多脂肪”义。'),M('The fatty oil contained almost no fat and consisted entirely of pure water.','The watery liquid contained almost no fat and consisted largely of water.','脂肪含量很低的液体不能称为 fatty。'),[Q('fatty',1,1,'A fatty food contains?','a relatively high proportion of fat','no calories of any kind','only mineral salts','fatty 表示含脂肪较多。'),Q('fatty',2,1,'Which meal is most likely described as fatty?','fried pork belly with visible layers of fat','plain steamed rice with no added oil','a glass of tap water','可见肥肉和油炸使猪肉更脂肪丰富。'),Q('fatty',3,1,'A doctor asks a patient to reduce fatty snacks. The doctor means snacks that?','contain a lot of fat','are unusually cold','taste only of salt','fatty 修饰食品时指脂肪含量高。'),Q('fatty',4,1,'Which word is closest in meaning to fatty here?','greasy','watery','fibrous','greasy 可表示油脂较多。')]);
P('fatuous','fatuous 来自拉丁语 fatuus“愚蠢的、空洞的”，可形容缺乏常识的言行，也可形容愚蠢的自鸣得意。',C('fatuous.s2','谈话反应','He gave a fatuous grin after taking credit for a calculation he had not checked, apparently pleased with his own cleverness.','他把未经核对的计算成果归功于自己后露出自鸣得意的傻笑，似乎很满意自己的聪明。','He gave a fatuous grin / after taking credit for a calculation he had not checked / apparently pleased / with his own cleverness.','fatuous 修饰 grin，强调愚蠢而自满；after 引出表情出现的情境。','未经核查却自夸并露出傻气的得意表情，体现 s2。'),M('Her fatuous proposal carefully addressed each risk and offered a sensible, evidence-based solution.','Her thoughtful proposal carefully addressed each risk and offered a sensible, evidence-based solution.','周全且基于证据的方案并不愚蠢。'),[Q('fatuous',1,1,'A fatuous remark is?','foolish and lacking good sense','carefully reasoned from evidence','a precise scientific measurement','fatuous 表示愚蠢、不明智。'),Q('fatuous',2,2,'A fatuous smile may look?','silly and smug','sad and ashamed','neutral and unreadable','该词也可指愚蠢而自鸣得意。'),Q('fatuous',3,1,'Which comment is fatuous?','“I know the bridge is safe because I dreamed about it.”','“The inspection found three cracked supports.”','“Let us wait for the engineer’s report.”','凭梦断定桥安全是缺乏常识的推断。'),Q('fatuous',4,1,'A fatuous boast usually reveals?','silly self-satisfaction','careful humility','verified expertise','夸耀并显露愚蠢的自满符合该词。')]);
P('faultfinding','faultfinding 由 fault 与 finding 合成，指不断寻找小缺点并挑剔批评的习惯或行为。',C('faultfinding.s1','同事评价','The reviewer’s faultfinding focused on a comma while ignoring the report’s accurate data and clear explanation.','评论者吹毛求疵地盯着一个逗号，却忽略了报告准确的数据和清楚的解释。','The reviewer’s faultfinding focused on a comma / while ignoring the report’s accurate data / and clear explanation.','faultfinding 作名词描述挑剔行为；while 引出对细节与整体质量的反差。','只抓一个小标点错误而无视内容质量，体现吹毛求疵。'),M('Her faultfinding praised every detail and never searched for any small defect.','Her careful review praised strong points while identifying genuine defects.','从不找缺点的赞扬并非 faultfinding。'),[Q('faultfinding',1,1,'Faultfinding means?','continually searching for small defects','repairing a broken machine','finding a lost object outdoors','faultfinding 指不停挑错、批评小缺点。'),Q('faultfinding',2,1,'Which response sounds faultfinding?','rejecting a clear report because one heading is two millimeters too low','praising the report’s evidence and noting a major factual error','asking the author to check a broken link','只因无关紧要的微小排版细节否定整份报告体现挑剔。'),Q('faultfinding',3,1,'A faultfinding colleague is most likely to?','criticize minor flaws repeatedly','offer balanced feedback once','ignore every detail completely','反复批评小瑕疵是 faultfinding 的特征。'),Q('faultfinding',4,1,'Which attitude contrasts with faultfinding?','constructive appreciation','nitpicking','persistent criticism','建设性肯定与吹毛求疵相对。')]);
P('faunal','faunal 由 fauna（某地区或时期的动物群）加形容词后缀 -al 构成，指与动物区系有关的。',C('faunal.s1','生态调查','The ecologist compared faunal surveys from two wetlands to see whether the new drainage channel had changed which species could live there.','生态学家比较了两处湿地的动物区系调查，以了解新排水渠是否改变了当地适宜生存的物种。','The ecologist compared faunal surveys from two wetlands / to see whether the new drainage channel had changed / which species could live there.','faunal 修饰 surveys，说明调查对象为动物群；whether 引出研究问题。','调查比较当地动物物种，属于动物区系研究。'),M('The faunal inventory listed only tree species and omitted every animal observed at the site.','The floral inventory listed only tree species and omitted every animal observed at the site.','仅记录植物的清单是 floral，而不是 faunal。'),[Q('faunal',1,1,'A faunal survey records?','animal species in an area','the chemical makeup of rocks','the language spoken by residents','faunal 与地区动物群有关。'),Q('faunal',2,1,'Which finding belongs in a faunal report?','a rare frog breeds in the marsh','the granite contains quartz','the village road was repaved','稀有蛙种是动物调查内容。'),Q('faunal',3,1,'A faunal change in a forest concerns changes among?','the animals living there','the color of its mineral soil only','the names of its streets','faunal 关注动物种群变化。'),Q('faunal',4,1,'The closest contrast to faunal in a study of life is?','floral','zoological','animal-related','floral 与动物相关的 faunal 对应植物。')]);
P('fauvism','fauvism 源自法语 Fauves“野兽”，是 20 世纪初法国绘画运动名称，常以强烈、非自然的色彩著称。',C('fauvism.s1','艺术史课程','The lecture introduced Fauvism through paintings that used vivid orange trees and violet shadows instead of naturalistic landscape colours.','课程通过几幅画介绍野兽派：画中树木呈鲜橙色、阴影为紫色，而非采用写实风景色彩。','The lecture introduced Fauvism through paintings / that used vivid orange trees and violet shadows / instead of naturalistic landscape colours.','Fauvism 通常首字母大写作为艺术运动名称；instead of 对照自然色与主观强烈色彩。','鲜艳而非自然的色彩是野兽派绘画的代表特征。'),M('The painting was an example of Fauvism because it carefully copied every hue from a realistic photograph.','The painting was an example of photorealism because it carefully copied every hue from a realistic photograph.','忠实复制照片色彩符合写实风格，不符合野兽派的强烈任意用色特点。'),[Q('fauvism',1,1,'Fauvism is best known as a movement in?','early twentieth-century French painting','medieval shipbuilding','modern computer programming','Fauvism 是法国绘画运动。'),Q('fauvism',2,1,'A painting influenced by Fauvism may use?','bold, non-naturalistic colours','only shades copied exactly from a photograph','no colour at all under any circumstances','强烈、非自然的色彩常见于野兽派。'),Q('fauvism',3,1,'Why did the movement’s name refer to “wild beasts”?','critics reacted to the paintings’ forceful colour and style','the artists painted only animals in zoos','the works were made by trained falcons','“野兽”名称与当时观者对鲜烈画风的反应有关。'),Q('fauvism',4,1,'Which art choice is closest to Fauvism?','painting green shadows in vivid red','matching every colour to measured reality','leaving the canvas entirely unpainted','用鲜红代替真实绿色阴影体现主观用色。')]);
P('favorable','favorable 由 favor 加 -able 构成，表示有利于目标、条件良好，或评价中积极赞许。',C('favorable.s1','项目评审','The panel gave the proposal a favorable review because its budget was transparent, its timeline realistic, and its safety plan complete.','评审组对提案评价积极，因为预算透明、时间表现实，安全计划也完整。','The panel gave the proposal a favorable review / because its budget was transparent / its timeline realistic / and its safety plan complete.','favorable review 表示正面评价；because 后列出赞许的具体理由。','评审认为提案质量好并给出积极评价，符合词义。'),M('The committee’s favorable report condemned the proposal as unsafe and recommended rejecting it.','The committee’s unfavorable report condemned the proposal as unsafe and recommended rejecting it.','谴责方案并建议拒绝属于负面评价，不是 favorable。'),[Q('favorable',1,1,'A favorable opinion is?','positive and approving','hostile and disapproving','unrelated to the subject','favorable 可指积极赞许的。'),Q('favorable',2,1,'Which weather is favorable for drying paint outdoors?','warm, dry air with a light breeze','a cold downpour','dense fog and freezing rain','温暖干燥有微风有利于油漆干燥。'),Q('favorable',3,1,'A favorable contract term would?','protect the party it benefits','make the agreement impossible to read','remove every obligation from both parties','有利条款会保护受益一方。'),Q('favorable',4,1,'The closest opposite of a favorable review is?','critical','approving','positive','critical 在此表示批评性的负面评价。')]);
P('favorably','favorably 由 favorable 加 -ly 构成，可表示赞许地，也可表示某条件对结果有利地。',C('favorably.s1','面试反馈','The hiring committee viewed Lina favorably after she explained how she had resolved a difficult scheduling conflict without blaming her colleagues.','招聘委员会在听取莉娜如何不责怪同事、解决棘手排班冲突后，对她印象良好。','The hiring committee viewed Lina favorably / after she explained how she had resolved a difficult scheduling conflict / without blaming her colleagues.','view someone favorably 表示对某人持赞许看法；after 从句说明形成印象的依据。','委员会对她的能力和做事方式给予积极评价，符合词义。'),M('The examiner viewed the application favorably and therefore rejected it for every serious defect.','The examiner viewed the application unfavorably and rejected it for serious defects.','因严重缺陷而拒绝通常表示负面评价，不应称 favorably。'),[Q('favorably',1,1,'If a proposal is received favorably, it is?','welcomed or approved','ignored without comment','rejected with anger','favorably 表示赞许地、积极地。'),Q('favorably',2,1,'A mild wind may affect a sailing race favorably by?','helping boats move toward the finish','blowing every boat backward','removing all water from the course','有助前进的风对比赛结果有利。'),Q('favorably',3,1,'Choose the natural collocation.','the judge looked favorably on the evidence','the judge looked favorably under the evidence','the judge favorably looked into evidence yesterday always','look favorably on 表示对某事持积极看法。'),Q('favorably',4,1,'A candidate is viewed favorably when interviewers?','form a positive impression of the candidate','decide never to read the application','confuse the candidate with a reference book','表示面试官对候选人印象良好。')]);
P('favored','favored 是 favor 的过去分词形容词，可指受到特别优待者，也可指处于有利位置的一方。',C('favored.s1','竞赛分组','Because the favored school had won the regional title three years in a row, reporters expected it to reach the final again.','由于这所被看好的学校连续三年赢得地区冠军，记者预计它会再次进入决赛。','Because the favored school had won the regional title three years in a row / reporters expected it / to reach the final again.','favored 修饰 school，表示被看好、有胜算；because 引出其优势依据。','连年夺冠使该校成为受看好的一方，符合有利地位义。'),M('The favored candidate received no support, had the weakest record, and was expected to lose by everyone.','The unfavored candidate received no support, had the weakest record, and was expected to lose by everyone.','毫无支持且被认为必败与 favored（占优、被看好）相反。'),[Q('favored',1,1,'The favored team in a match is?','the one expected to have an advantage','the team already removed from the league','the team with no players','favored 常指被看好或占优的一方。'),Q('favored',2,1,'A favored employee may receive?','special preference or better opportunities','less pay than everyone by definition','no access to workplace information','受到优待的人可能得到特别机会。'),Q('favored',3,1,'Which sentence uses favored to mean “preferred”?','Blue was the favored choice among the voters.','The favored bridge collapsed under a test.','The favored report was never selected.','voters preferred blue，体现首选义。'),Q('favored',4,1,'Why was the runner favored to win?','her recent times were faster than her rivals’','she had never entered a race','the finish line had been removed','成绩领先使她更有胜算。')]);
P('favorite','favorite 可作名词或形容词，来自 favor 加 -ite；表示最喜欢的人或事物，也可修饰最受喜爱的对象。',C('favorite.s2','日常偏好','The café’s favorite dessert was the lemon tart, and the baker made an extra tray whenever the annual street festival brought a larger crowd.','这家咖啡馆最受欢迎的甜点是柠檬挞；每逢年度街头节带来更多顾客，面包师就会多做一盘。','The café’s favorite dessert was the lemon tart / and the baker made an extra tray / whenever the annual street festival brought a larger crowd.','favorite 作形容词修饰 dessert；favorite 可按美式拼法使用，英式常见 favourite。','柠檬挞被描述为最受喜爱的甜点，符合 s2。'),M('My favorite book is one I dislike most and refuse to read.','My least favorite book is one I dislike most and refuse to read.','最喜欢与最不喜欢含义相反；least favorite 才符合后半句。'),[Q('favorite',1,1,'As a noun, a favorite is?','a person or thing someone likes best','a person who has never been chosen','a tool for measuring rainfall','favorite 可作名词，指最喜欢的人或事物。'),Q('favorite',2,2,'In “my favorite song,” favorite is?','an adjective describing the song liked best','a verb meaning to compose a song','a noun for a musical instrument','此处 favorite 修饰 song，为形容词。'),Q('favorite',3,1,'The team is the tournament favorite because it?','is expected to win','has already forfeited every match','is not allowed to compete','favorite 可指最被看好夺冠者。'),Q('favorite',4,1,'Which sentence uses favorite as a noun?','The old oak is a favorite with local photographers.','She chose her favorite coat.','The favorite color was listed first.','a favorite 作名词，表示受喜爱的人或物。')]);
P('fealty','fealty 经古法语 féauté 源自拉丁语 fidelitas“忠诚”，历史上指封建附庸对领主承担的效忠义务，现代可泛指忠诚。',C('fealty.s1','封建历史','The vassal swore fealty to the queen, promising military service and loyalty in exchange for protection and the use of the estate.','附庸向女王宣誓效忠，承诺提供军役并忠于她，以换取保护和庄园使用权。','The vassal swore fealty to the queen / promising military service and loyalty / in exchange for protection / and the use of the estate.','swear fealty to + 领主；promising 补充封建效忠的具体义务。','附庸承诺忠诚及军役，符合历史上的效忠义务。'),M('The vassal swore fealty to the queen while promising to betray her and join her enemy.','The vassal broke his oath of fealty by promising to betray the queen and join her enemy.','宣誓效忠与承诺背叛相冲突，应改为违背誓约。'),[Q('fealty',1,1,'In a medieval setting, fealty was?','an oath of loyalty owed by a vassal to a lord','a tax paid by a merchant at a port','a tool used to repair armor','fealty 指附庸对领主的效忠义务。'),Q('fealty',2,1,'A vassal showing fealty might?','provide service to the lord who protects the estate','refuse every oath and attack the lord','sell the estate to a stranger without consent','提供承诺的服务体现 fealty。'),Q('fealty',3,1,'The modern figurative use of fealty still emphasizes?','loyalty','measurement','seasonal farming','现代泛义仍表示忠诚。'),Q('fealty',4,1,'Which verb commonly goes with fealty?','swear','evaporate','compile','常见搭配为 swear fealty。')]);
P('fearsome','fearsome 由 fear 加 -some 构成，表示因体形、力量、行为或名声而令人害怕、敬畏。',C('fearsome.s1','野生动物','The fearsome-looking boar charged at the fence, but the ranger kept the visitors behind the barrier until it retreated into the woods.','那头看起来凶猛的野猪冲向围栏，但护林员让游客待在屏障后，直到野猪退回树林。','The fearsome-looking boar charged at the fence / but the ranger kept the visitors behind the barrier / until it retreated into the woods.','fearsome 修饰 boar，描述其令人害怕的外观；but 引出安全应对。','野猪冲击围栏、令游客避开，呈现可怕且有威胁的形象。'),M('The fearsome machine was harmless, silent, and unable to move, yet everyone was terrified of its power.','The harmless machine was silent and unable to move, so it posed no danger.','无害且不能移动的机器并不能说明它令人畏惧。'),[Q('fearsome',1,1,'A fearsome reputation is one that?','makes people feel afraid or intimidated','makes everyone feel sleepy','is based only on a person’s height','fearsome 表示令人害怕、敬畏的。'),Q('fearsome',2,1,'Which storm would be called fearsome?','one with destructive winds and huge waves','a light drizzle on a calm day','a cloudless morning with no wind','强风和巨浪构成令人畏惧的风暴。'),Q('fearsome',3,1,'The fearsome opponent worried the team because the opponent?','had a record of powerful, difficult victories','had never played a match','had left the stadium before the game','强大而难以战胜的对手令人畏惧。'),Q('fearsome',4,1,'Choose the closest opposite of fearsome.','harmless','terrifying','formidable','harmless 表示无害，不令人害怕。')]);
P('feasibility','feasibility 由 feasible 加 -ity 构成，feasible 来自法语 faisable（可做到的）；表示计划成功实施的可能性或实际可操作性。',C('feasibility.s2','工程实施','The team tested the feasibility of installing solar panels on the old roof by checking its load capacity, wiring, and maintenance access.','团队通过检查旧屋顶的承重能力、电路和维护通道，测试安装太阳能板是否切实可行。','The team tested the feasibility of installing solar panels on the old roof / by checking its load capacity, wiring, and maintenance access.','feasibility of + 名词或动名词；检查结构和维护条件体现实际可操作性 s2。','工程团队核查安装所需条件，评估是否可实际执行。'),M('The team proved feasibility by showing that the roof could not bear any additional weight and had no safe access.','The team disproved feasibility by showing that the roof could not bear additional weight and had no safe access.','缺乏承重能力和安全通道是不可行证据，而非可行性证明。'),[Q('feasibility',1,1,'A feasibility study asks whether a plan?','can realistically be carried out','has already become a historical event','is popular on social media','feasibility 评估方案是否能实施。'),Q('feasibility',2,2,'A plan’s feasibility may depend on whether workers can?','operate and maintain it in practice','describe it with a catchy title','remember its name','可操作、可维护是实际可行性的条件。'),Q('feasibility',3,1,'Which question tests feasibility?','Can the bridge support the expected traffic safely?','Does the bridge look attractive in a painting?','Who first invented the word bridge?','承重能力检验桥梁能否实际安全使用。'),Q('feasibility',4,1,'If no materials or funds are available, a project’s feasibility is?','low','certain','unrelated to whether it can be done','缺少材料和资金会降低可行性。')]);
P('feathery','feathery 由 feather 加 -y 构成，表示由羽毛组成、带羽毛状结构，或轻软如羽毛。',C('feathery.s1','植物描写','The fern’s feathery fronds bent in the breeze, their finely divided leaves casting delicate shadows across the damp stone path.','蕨类植物羽毛般的叶片在微风中弯曲，细密分裂的叶子把柔和的影子投在潮湿的石径上。','The fern’s feathery fronds bent in the breeze / their finely divided leaves casting delicate shadows / across the damp stone path.','feathery 修饰 fronds，指叶片羽毛状分裂；their 指代蕨叶。','细密分裂且轻柔的叶片呈羽毛形态，符合义项。'),M('The feathery fronds were solid blocks of stone with no delicate or divided leaves.','The stony structures were solid blocks with no delicate or divided leaves.','石块没有羽毛般轻柔、分裂的结构。'),[Q('feathery',1,1,'A feathery plant has leaves or parts that look?','soft and divided like feathers','hard and smooth like metal','round and solid like stones','feathery 指羽毛状或轻软的外观。'),Q('feathery',2,1,'Which description fits a feathery cloud?','wispy and soft-edged','dense like a concrete wall','sharp like a metal blade','轻软纤细的云边可称 feathery。'),Q('feathery',3,1,'A costume with feathery trim is decorated with?','feathers or feather-like material','heavy steel plates','plain unmarked paper','feathery 也可指由羽毛装饰。'),Q('feathery',4,1,'The closest contrast to a feathery texture is?','coarse and rigid','soft and airy','finely divided','坚硬粗糙与轻软羽毛状相反。')]);
P('featureless','featureless 由 feature 与否定后缀 -less 构成，表示缺少显著特征，外观单调或无法辨认。',C('featureless.s1','地貌描写','In the fog, the hikers crossed a featureless plateau where no tree, ridge, or building offered a landmark for navigation.','雾中，徒步者穿过一片毫无特色的高原，那里没有树木、山脊或建筑可作导航地标。','In the fog / the hikers crossed a featureless plateau / where no tree, ridge, or building / offered a landmark for navigation.','featureless 修饰 plateau，说明缺少可辨识特征；where 从句列举缺少的地标。','没有可供辨认或导航的显著景物，体现 featureless。'),M('The featureless skyline was easy to identify because three bright towers dominated it.','The distinctive skyline was easy to identify because three bright towers dominated it.','醒目的塔楼构成明显特征，不能说 skyline 毫无特色。'),[Q('featureless',1,1,'A featureless landscape has?','no notable or distinguishing details','many unique landmarks','a clear set of recognizable buildings','featureless 表示缺少明显特点。'),Q('featureless',2,1,'Which surface might be called featureless?','a blank wall with no marks or decoration','a mural filled with recognizable figures','a map covered in labeled roads','无痕无装饰的空白墙缺少特点。'),Q('featureless',3,1,'A face in a blurry photograph may be featureless because it?','shows no details that distinguish the person','has a scar and a bright tattoo','is sharply focused with clear eyes','模糊而无法分辨五官细节可称 featureless。'),Q('featureless',4,1,'Choose the closest opposite of featureless.','distinctive','uniform','plain','distinctive 表示有明显特点。')]);
P('fecund','fecund 来自拉丁语 fecundus“多产的、肥沃的”，可形容土地或生物繁殖力强，也可形容创造力丰富。',C('fecund.s1','土壤与种植','The fecund valley supported several harvests each year because its deep soil retained moisture and nutrients through the dry season.','这片肥沃的山谷每年能支持多次收成，因为深厚的土壤在旱季仍能保留水分和养分。','The fecund valley supported several harvests each year / because its deep soil retained moisture and nutrients / through the dry season.','fecund 修饰 valley，指土地生产力高；because 给出土壤条件。','多次收成及保水保肥说明土地肥沃多产。'),M('The fecund soil produced no crops, lacked nutrients, and killed every seedling planted in it.','The barren soil produced no crops, lacked nutrients, and killed every seedling planted in it.','贫瘠且不能生长作物与 fecund 的肥沃义相反。'),[Q('fecund',1,1,'Fecund farmland is?','highly productive and fertile','covered permanently by ice','unable to support any growth','fecund 可形容土地肥沃多产。'),Q('fecund',2,1,'A fecund writer is one who?','produces many imaginative ideas or works','has never written a sentence','copies one paragraph repeatedly','比喻义表示创造力旺盛、多产。'),Q('fecund',3,1,'Which animal population is fecund?','one that reproduces readily','one that cannot produce offspring','one consisting only of fossils','繁殖能力强体现 fecund。'),Q('fecund',4,1,'The closest contrast to a fecund orchard is a?','barren orchard','productive orchard','fruitful orchard','barren 与肥沃、多产相反。')]);
P('fecundity','fecundity 由 fecund 加 -ity 构成，指土地、动物繁殖能力或创造性产出的多产性。',C('fecundity.s1','生态变化','Researchers measured the fish population’s fecundity by counting eggs and tracking how many developed into healthy young.','研究人员通过统计鱼卵并追踪其中多少发育成健康幼鱼，来测量该鱼群的繁殖力。','Researchers measured the fish population’s fecundity / by counting eggs / and tracking how many developed into healthy young.','measure fecundity by + 动名词说明测量方式；由卵到幼鱼的数量用于评估繁殖能力。','统计卵和后代成活情况测量繁殖力，符合义项。'),M('The low fecundity of the fish population meant every female produced thousands of surviving young.','The high fecundity of the fish population meant many females produced numerous young.','每只雌鱼都产生大量成活后代显示繁殖力高，而非低。'),[Q('fecundity',1,1,'A species’ fecundity concerns its ability to?','produce offspring','change color in sunlight','move through water quickly','fecundity 指繁殖能力。'),Q('fecundity',2,1,'A writer’s fecundity is shown by?','producing many original works','publishing nothing for decades','repeating one line without change','用于创作时可指作品产出丰盛。'),Q('fecundity',3,1,'Which measurement could estimate soil fecundity?','how much healthy crop growth it supports','the number of road signs nearby','the color of a farmer’s coat','土壤支持作物生长的能力体现肥沃多产。'),Q('fecundity',4,1,'The closest word to biological fecundity is?','fertility','sterility','hibernation','fertility 表示生育或繁殖能力。')]);
P('federalism','federalism 由 federal 加 -ism 构成，常指中央与地方政府分权的联邦制度，也可指支持该制度的政治思想。',C('federalism.s1','宪政安排','Under federalism, the national government handles currency and defense while regional governments set many local education policies.','在联邦制下，国家政府负责货币和国防，而地方政府制定许多本地教育政策。','Under federalism / the national government handles currency and defense / while regional governments set many local education policies.','federalism 作制度名词；while 对照中央与地方各自掌握的权力。','权力由中央和地区政府分担，符合制度义 s1。'),M('The country practiced federalism by giving every decision to one central office and abolishing all regional governments.','The country practiced centralization by giving every decision to one central office and abolishing all regional governments.','所有权力集中且取消地方政府与 federalism 的分权相反。'),[Q('federalism',1,1,'Federalism is a system in which?','power is shared between central and regional governments','every village sets the national currency','all local governments are abolished','联邦制在中央与地方之间分享权力。'),Q('federalism',2,2,'A political supporter of federalism believes that?','shared government powers are desirable','a single ruler should control every local issue','regional government should never exist','s2 是对权力分享制度的政治主张。'),Q('federalism',3,1,'Which arrangement best illustrates federalism?','the center manages defense while provinces control local schools','one office controls every school and road across the country','each household issues its own national passport','中央和地方分别负责不同事务体现分权。'),Q('federalism',4,1,'Federalism differs from strict centralization because federalism?','reserves meaningful powers for regional units','removes every regional institution','places every law in one person’s hands','保留地方权力与高度中央集权相对。')]);
P('federalist','federalist 由 federal 加 -ist 构成，可指支持联邦制或联邦主义者，也指美国早期支持较强中央政府的联邦党人。',C('federalist.s2','美国建国史','In the early United States, a Federalist argued for a stronger national government than many opponents wanted under the new Constitution.','在美国早期，一位联邦党人主张新宪法下的国家政府应比许多反对者所希望的更强。','In the early United States / a Federalist argued for a stronger national government / than many opponents wanted / under the new Constitution.','Federalist 首字母大写时常指美国历史政党成员；than 比较双方主张。','美国建国时期支持较强中央政府体现历史特定义 s2。'),M('The early American Federalist opposed the Constitution and campaigned to weaken the national government.','The early American Anti-Federalist opposed the Constitution and campaigned to weaken the national government.','反对宪法、削弱中央政府更符合当时 Anti-Federalist，而非联邦党人。'),[Q('federalist',1,1,'A modern federalist generally supports?','sharing governing powers between national and regional levels','abolishing all regional governments','replacing elections with hereditary rule','现代义指支持联邦制或权力分享。'),Q('federalist',2,2,'An early American Federalist typically favored?','a stronger central government under the Constitution','rejecting the Constitution and removing national authority','a monarchy with no elected legislature','美国早期 Federalists 支持宪法和较强中央政府。'),Q('federalist',3,1,'Which sentence uses federalist in the broad political sense?','The federalist proposed that provinces keep some authority.','The federalist sharpened a kitchen knife.','The federalist measured rainfall in a greenhouse.','广义联邦主义者支持中央与地方分权。'),Q('federalist',4,2,'Why is the capitalized Federalist in a history chapter specific?','it can name a member of an early U.S. political party','it always names any supporter of local sports','it is a title for a medieval farmer','大写词用于美国早期政党历史语境。')]);
P('feeder','feeder 可由 feed 加 -er 构成，指供食容器或喂养者，也指汇入较大主干的支线道路、铁路或溪流。',C('feeder.s2','交通网络','The feeder road carries traffic from three small villages to the main highway, where drivers can continue toward the regional hospital.','这条支线公路把三个小村庄的车辆引向主干公路，司机在那里可继续前往地区医院。','The feeder road carries traffic from three small villages to the main highway / where drivers can continue / toward the regional hospital.','feeder road 指把交通引入主干道的支路；where 指主干高速公路。','小路汇入较大的主干公路，符合 s2。'),M('The feeder road carried traffic away from the highway and ended before reaching any village.','The access road carried traffic away from the highway and ended before reaching any village.','该道路不汇入主干线，不能称将交通引向主路的 feeder road。'),[Q('feeder',1,2,'A feeder stream is one that?','flows into a larger river','begins underground and ends in a desert','moves parallel to a river but never joins it','feeder 可指汇入较大河流的小支流。'),Q('feeder',2,1,'A bird feeder is?','a container that provides food for birds','a device that records birdsong','a nest built only by eagles','供鸟类取食的容器是 feeder。'),Q('feeder',3,2,'A feeder railway typically?','connects a smaller town or line to a major route','replaces every national rail line','carries food for farm animals','支线铁路把小地方接到主要线路。'),Q('feeder',4,1,'Which road is a feeder road?','a local road that channels cars onto a highway','a motorway with no connecting roads','a footpath ending at a private garden','将车辆引向高速公路的地方道路属 feeder road。')]);
P('feint','feint 来自古法语 feinte（伪装、假动作），可作名词指佯攻，也可作动词表示用假动作诱使对手判断失误。',C('feint.s2','击剑战术','The fencer feinted toward the opponent’s shoulder, drew the parry high, and then scored with a quick thrust at the open torso.','击剑手假装刺向对手肩部，引得对方把剑高位格挡，随后迅速刺向暴露的躯干得分。','The fencer feinted toward the opponent’s shoulder / drew the parry high / and then scored / with a quick thrust at the open torso.','feint 作动词表示佯攻；draw the parry 描述骗出防守动作。','先做假动作诱导对方，再攻击空当，体现 s2。'),M('The boxer feinted by announcing his exact punch in advance and making no deceptive movement.','The boxer feinted by pretending to punch high before striking low.','提前告知真实出拳且不做假动作并非佯攻。'),[Q('feint',1,2,'A boxer feints by?','pretending to attack one way to create an opening elsewhere','announcing the exact punch and standing still','blocking every blow without moving','feint 动词指假装进攻以诱导对手。'),Q('feint',2,1,'In fencing, a feint is?','a deceptive move that draws the opponent’s defense','a final score after the bout','a protective mask worn on the head','名词 feint 指佯攻或假动作。'),Q('feint',3,2,'A successful feint usually makes the opponent?','react to a false threat','ignore every real attack','leave the match permanently','假动作让对手对虚假威胁做出反应。'),Q('feint',4,1,'Which contrast best fits feint in sport?','a genuine attack','a deceptive move','a sham threat','feint 是假动作，genuine attack 是真实进攻。')]);
P('feldspar','feldspar 的名字来自德语 Feldspat（田野之石）；它指地壳中常见的一组硅酸盐矿物，通常可见于花岗岩等岩石。',C('feldspar.s1','地质样本','Under the hand lens, the granite showed pale feldspar crystals alongside darker mica and quartz grains.','在手持放大镜下，花岗岩中可见浅色长石晶体，以及颜色较深的云母和石英颗粒。','Under the hand lens / the granite showed pale feldspar crystals / alongside darker mica and quartz grains.','feldspar 是矿物名；alongside 列出同一岩石中的其他矿物。','浅色长石晶体出现在花岗岩中，符合常见地质特征。'),M('The geologist identified the feldspar as a group of flying insects found in the sample.','The geologist identified the feldspar as a group of light-colored silicate minerals found in the sample.','feldspar 是矿物类群，不是昆虫。'),[Q('feldspar',1,1,'Feldspar is a group of?','common rock-forming minerals','freshwater insects','soft garden vegetables','feldspar 指常见造岩矿物。'),Q('feldspar',2,1,'A geologist may find feldspar in?','granite','a flock of migrating birds','a glass of distilled water','长石是花岗岩中的常见矿物。'),Q('feldspar',3,1,'Which property fits feldspar in a rock sample?','it is a mineral that forms part of the Earth’s crust','it is a living root system','it is a measurement of air temperature','feldspar 属于地壳矿物。'),Q('feldspar',4,1,'Feldspar differs from quartz because they are?','different mineral groups','two names for the same animal','both types of weather forecast','两者是不同矿物类群。')]);
P('felicity','felicity 经法语源自拉丁语 felicitas“幸福、幸运”，可指强烈幸福感，也可指恰切悦耳的表达方式。',C('felicity.s1','写作评论','The reviewer praised the felicity of the phrase “a city waking in blue,” which captured both the dawn light and the streets’ slow return to life.','评论者称赞“蓝色中醒来的城市”这一说法贴切悦耳，既捕捉了黎明光线，也描绘了街道慢慢恢复生气。','The reviewer praised the felicity of the phrase / “a city waking in blue” / which captured both the dawn light / and the streets’ slow return to life.','felicity 可指措辞恰当；of the phrase 指其表达效果。','短语准确、生动地表现景象，体现表达上的恰切。'),M('The felicity of his sentence made it confusing, inaccurate, and impossible to understand.','The infelicity of his sentence made it confusing, inaccurate, and impossible to understand.','混乱不准确的表达体现不恰当，而非 felicity。'),[Q('felicity',1,1,'A felicity of expression is?','an apt and pleasing way to say something','a long list of unrelated words','a failure to pronounce every sound','felicity 可指贴切优美的措辞。'),Q('felicity',2,1,'The felicity of a family’s reunion refers to its?','great happiness','legal responsibility','lack of communication','felicity 也指幸福或快乐。'),Q('felicity',3,1,'Which sentence shows felicity in wording?','“The rain stitched silver lines across the lake.”','“Thing water did thing near place.”','“The lake was a number of seven.”','生动而恰切的比喻体现表达 felicity。'),Q('felicity',4,1,'The closest contrast to felicity of style is?','awkwardness','apt phrasing','elegance','awkwardness 与表达恰切相反。')]);
P('fell','fell 是 fall 的使役动词，源自古英语 fellan，表示通过砍伐或击打使树、人或动物倒下。',C('fell.s1','林业作业','The crew felled the diseased ash tree in sections, lowering each branch with a rope to keep it from damaging the nearby fence.','工人分段砍倒了患病的白蜡树，并用绳索放下每根树枝，以免砸坏附近围栏。','The crew felled the diseased ash tree in sections / lowering each branch with a rope / to keep it from damaging the nearby fence.','fell + 树木表示砍倒；lowering 说明控制树枝落下的操作。','树木被工人砍倒，符合动词 fell 的使役义。'),M('The crew felled the tree by planting it upright and making its trunk grow taller.','The crew felled the tree by cutting through its trunk until it toppled.','使树继续直立生长与将其砍倒的动作相反。'),[Q('fell',1,1,'To fell a tree is to?','cut it down so it falls','plant it in a deeper hole','measure the rings without cutting it','动词 fell 表示砍倒树木。'),Q('fell',2,1,'A warrior felled an opponent by?','striking or knocking the opponent down','helping the opponent stand up','writing the opponent’s name on a list','fell 可表示击倒人或动物。'),Q('fell',3,1,'Which sentence uses fell as a verb?','Workers felled two old pines beside the road.','The leaves fell from the tree in autumn.','The timber felt smooth after sanding.','felled 是及物动词 fell 的过去式，表示砍倒。'),Q('fell',4,1,'In “the blow felled him,” felled means the blow?','caused him to fall','helped him climb','taught him to speak','使人倒下是 fell 的动词义。')]);
P('felony','felony 经古法语 felonie“邪恶、重罪”进入英语；在区分 felony 与较轻罪行的法律体系中，指严重刑事犯罪，具体分类因司法辖区而异。',C('felony.s1','司法分类','The prosecutor charged the suspect with a felony, but the court first had to determine whether the evidence met the legal standard for that offense.','检察官以重罪起诉嫌疑人，但法院首先必须判断证据是否达到该罪名的法律标准。','The prosecutor charged the suspect with a felony / but the court first had to determine / whether the evidence met the legal standard / for that offense.','charge someone with a felony 表示以重罪起诉；but 强调指控仍须经过法律审查。','该词在此指法律体系划分的严重刑事罪。'),M('The court called a minor parking violation a felony in every country and legal system.','The court called the alleged offense a felony under the jurisdiction’s applicable criminal law.','felony 的适用范围及分级因司法辖区而异，不能说所有轻微违规在各地都属重罪。'),[Q('felony',1,1,'A felony is generally?','a serious criminal offense in legal systems using that category','a minor library fine','a civil disagreement about a fence','felony 指重罪类刑事犯罪。'),Q('felony',2,1,'Whether conduct counts as a felony can depend on?','the laws of the jurisdiction','the defendant’s favorite color','the weather on the trial date','罪名分级须依据当地法律。'),Q('felony',3,1,'Which institution determines a felony charge in court?','a court applying the relevant law','a weather station','a sports club','法院依据法律审理刑事罪名。'),Q('felony',4,1,'A felony is usually contrasted with?','a less serious misdemeanor or minor offense','a verified scientific fact','a type of farm tool','felony 通常与较轻罪行相对。')]);
P('felt','felt 源自古英语 felt，指通过压合羊毛等纤维制成的无纺布材料；本条词义为名词，不是 feel 的过去式。',C('felt.s1','手工材料','She cut a circle of thick felt to cushion the wooden box, choosing a dark color that would not show dust between cleanings.','她剪下一块厚毛毡圆片垫在木盒里，并选了不易在两次清洁间显灰的深色。','She cut a circle of thick felt / to cushion the wooden box / choosing a dark color / that would not show dust between cleanings.','felt 作不可数或材料名词；to cushion 说明毛毡垫片的用途。','压制纤维布料用于缓冲盒子，符合 felt 的材料义。'),M('The hat was made of felt, a liquid poured into a glass and drunk at breakfast.','The hat was made of felt, a fabric formed by pressing fibers together.','felt 是纤维压制成的布料，不是可饮用液体。'),[Q('felt',1,1,'Felt is a material made by?','pressing fibers such as wool together','weaving metal wires into a chain','freezing clean water into a block','毛毡通过压合纤维制成。'),Q('felt',2,1,'A felt pad under a chair leg can?','protect the floor from scratches','make the chair float','measure how tall the chair is','毛毡垫能保护地板不被刮擦。'),Q('felt',3,1,'Which item is most likely made from felt?','a soft craft sheet cut from compressed wool fibers','a pane of transparent glass','a steel cooking pot','压制羊毛纤维的手工片是毛毡。'),Q('felt',4,1,'In this entry, felt is a noun naming?','a textile material','the past tense of “feel” only','a legal punishment','本词条所列 felt 指毛毡材料。')]);
P('feminism','feminism 由 feminine/feminist 词族加 -ism 构成；现代英语中指主张女性享有平等权利机会的思想，也指争取平权的组织运动。',C('feminism.s2','社会运动史','The exhibit traced feminism through petitions, workplace campaigns, and legal reforms that sought equal voting, education, and employment rights for women.','展览通过请愿、职场运动和法律改革梳理女权运动史，这些行动争取女性平等的投票、教育和就业权利。','The exhibit traced feminism / through petitions, workplace campaigns, and legal reforms / that sought equal voting, education, and employment rights / for women.','feminism 可指争取平权的社会运动；that 从句解释运动目标。','请愿、运动和改革是争取女性平等权利的集体行动，符合 s2。'),M('The feminism campaign demanded that women lose the rights and opportunities already held by men.','The anti-feminist campaign demanded that women lose the rights and opportunities already held by men.','要求剥夺平等权利与 feminism 的平权目标相反。'),[Q('feminism',1,1,'Feminism as a belief argues that women should have?','equal rights and opportunities','fewer legal protections by definition','no access to education','feminism 的思想义主张平等权利与机会。'),Q('feminism',2,2,'A historical feminism movement might organize?','campaigns for women’s voting rights','a campaign to close every school','a contest to rank family names','争取投票权是女性平权运动的一部分。'),Q('feminism',3,1,'Which principle is consistent with feminism?','people should not be denied opportunities because of sex','only men may receive an education','women should have no legal voice','反对基于性别剥夺机会与女权平等主张一致。'),Q('feminism',4,2,'In a history text, feminism can refer to?','organized efforts to achieve women’s equality','the private habit of collecting stamps','a branch of mineral geology','feminism 也可指争取平权的组织运动。')]);
P('feminist','feminist 由 feminine 与 -ist 词族形成，可作名词指支持女性平等权利者，也可作形容词表示女权主义的、支持平权的。',C('feminist.s2','出版与评论','The feminist editor examined whether the textbook gave women scientists the same space and authority as their male colleagues.','这位女权主义编辑考察教材是否给予女性科学家与男性同行相同的篇幅和权威性。','The feminist editor examined / whether the textbook gave women scientists / the same space and authority / as their male colleagues.','feminist 作形容词修饰 editor；whether 引出平等呈现的评估标准。','编辑关注女性科学家的平等呈现，符合形容词义。'),M('The feminist scholar argued that women should be excluded from scientific education and public life.','The anti-feminist scholar argued that women should be excluded from scientific education and public life.','主张排除女性与 feminist 的平等权利立场相反。'),[Q('feminist',1,1,'As a noun, a feminist is someone who?','supports equal rights for women','studies only the mineral feldspar','opposes every form of education','feminist 名词指支持女性平等权利者。'),Q('feminist',2,2,'In “a feminist reading of the novel,” feminist is?','an adjective describing an approach concerned with gender equality','a noun naming the novel’s paper','a verb meaning to publish a book','此处 feminist 修饰 reading，是形容词。'),Q('feminist',3,1,'Which action is consistent with a feminist policy?','ensuring equal access to training and promotion','reserving all advanced courses for men','paying workers differently solely because of sex','保障平等培训晋升机会符合平权。'),Q('feminist',4,1,'The closest broad description of a feminist is?','an advocate of women’s equality','a critic of all women’s education','a person who studies only family trees','该词描述支持女性平等者。')]);
P('fencing','fencing 来自 fence（围栏、围起），可指用剑进行攻防的击剑运动，也可指栅栏或筑栏材料。',C('fencing.s1','体育训练','During fencing practice, both athletes saluted, tested the distance with quick footwork, and waited for the referee’s signal before attacking.','击剑训练中，两名运动员先行礼，再用快速步法试探距离，并在裁判发出信号后才进攻。','During fencing practice / both athletes saluted / tested the distance with quick footwork / and waited for the referee’s signal before attacking.','fencing 作运动名词；salute、footwork 和 referee 是击剑场景要素。','持剑运动员通过步法攻防，指击剑义 s1。'),M('The fencing match was won by planting wooden posts around the garden and attaching wire.','The gardening match was won by planting wooden posts around the garden and attaching wire.','立柱并装铁丝是筑栅栏，不是击剑比赛。'),[Q('fencing',1,1,'Fencing as a sport involves?','attacking and defending with a sword','building a house from stone','racing horses around a track','击剑是持剑攻防运动。'),Q('fencing',2,2,'The fencing around a garden means?','posts or material forming a barrier','a tournament with foil and épée','a set of rules for chess','fencing 也可指围栏或筑栏材料。'),Q('fencing',3,1,'A foil is equipment used in?','fencing','planting trees','measuring rainfall','foil 是击剑器械之一。'),Q('fencing',4,2,'Which sentence uses fencing to mean a barrier?','The farm repaired its fencing before the sheep arrived.','She won a medal in fencing.','The fencing referee checked the masks.','修理农场栅栏体现 s2。')]);
P('fend','fend 源于古英语 fendian“保卫”；可与 off 连用表示抵挡攻击，也可与 for oneself 连用表示自立、照料自己。',C('fend.s2','独立生活','After moving away for college, Ravi learned to fend for himself by budgeting, cooking simple meals, and arranging his own appointments.','搬去外地上大学后，拉维学会了自立：做预算、准备简单饭菜并自行安排预约。','After moving away for college / Ravi learned to fend for himself / by budgeting, cooking simple meals, / and arranging his own appointments.','fend for oneself 表示独立照料自己；by 后列出实现方式。','离家后自行管理生活，符合 s2。'),M('The new graduate could fend for himself only because his parents handled every meal, bill, and appointment.','The new graduate could not yet fend for himself because his parents handled every meal, bill, and appointment.','所有生活事务均由父母代办，说明他尚不能独立照料自己。'),[Q('fend',1,2,'To fend for yourself is to?','manage your needs without relying on help','attack strangers for no reason','wait for someone else to make every choice','fend for oneself 表示独立自理。'),Q('fend',2,1,'A goalkeeper fends off a shot by?','blocking or pushing the ball away','inviting the ball into the net','writing down the score before play','fend off 指抵挡、击退攻击。'),Q('fend',3,2,'A person learning to fend for herself may practice?','paying bills and preparing meals','asking others to do every task','avoiding all daily responsibilities','自理生活需要处理账单和做饭等日常事务。'),Q('fend',4,1,'Choose the natural phrase.','fend off an attacker','fend to an attacker','fend under an attacker','常见搭配 fend off 表示抵挡攻击。')]);
P('fender','fender 由 fend 加 -er 构成，可指车轮上方挡泥的弧形板，也可指缓和船只或物体碰撞的护垫、护栏。',C('fender.s1','车辆维修','The mechanic replaced the dented front fender because it no longer covered the wheel properly and scraped against the tire on turns.','修理工更换了凹陷的前挡泥板，因为它已无法妥善遮住车轮，转弯时还会刮到轮胎。','The mechanic replaced the dented front fender / because it no longer covered the wheel properly / and scraped against the tire on turns.','汽车 fender 通常位于车轮上方；because 说明损坏带来的问题。','损坏部件用于遮挡车轮和泥水，符合汽车挡泥板义。'),M('The car’s fender was the engine part that mixed fuel with air inside the cylinders.','The car’s carburetor was the engine part that mixed fuel with air inside the cylinders.','混合燃油与空气的是化油器，不是车轮上方的 fender。'),[Q('fender',1,1,'A car fender is usually located?','above or around a wheel','inside the fuel tank','on top of the steering wheel','挡泥板通常位于车轮上方或周围。'),Q('fender',2,1,'A boat may use a fender to?','cushion impact against a dock','steer the rudder underwater','measure the depth of the sea','船用护垫可缓冲靠岸碰撞。'),Q('fender',3,1,'Which repair involves a vehicle fender?','straightening the panel beside a damaged wheel','replacing the windshield wiper fluid','changing the radio station','修复车轮旁的车身板件属于挡泥板维修。'),Q('fender',4,1,'A fender protects by?','blocking mud or softening a collision','increasing the engine’s fuel supply','making the road longer','fender 可挡泥或缓冲碰撞。')]);
P('feral','feral 来自拉丁语 ferus“野生的、未驯服的”，常指家养物种逃逸后在野外繁衍，也可形容野蛮凶猛的状态。',C('feral.s1','野生动物管理','The feral cats avoided people but gathered near the abandoned barns, where conservation workers monitored them before arranging humane control.','这些野化的猫避开人群，却聚集在废弃谷仓附近；保护工作人员在安排人道管理前对它们进行监测。','The feral cats avoided people / but gathered near the abandoned barns / where conservation workers monitored them / before arranging humane control.','feral 修饰原本家养、如今在野外生活的猫；where 从句说明其活动地点。','家猫在野外生活且躲避人类，符合 feral 义。'),M('The feral house cat lived indoors, slept on its owner’s lap, and never left the heated apartment.','The domesticated house cat lived indoors, slept on its owner’s lap, and never left the heated apartment.','完全家养并生活在室内的猫不是野化的 feral 动物。'),[Q('feral',1,1,'A feral animal is often?','a domestic species living wild','a wild species trained to perform tricks','a farm animal kept safely in a pen','feral 常指家养物种回归野外状态。'),Q('feral',2,1,'Which animal is most likely feral?','a dog descended from pets that now lives independently in the forest','a trained sheepdog working with a shepherd','a pet rabbit in its indoor cage','脱离人类照料、在野外生活的狗符合 feral。'),Q('feral',3,1,'A feral population may create concern because it?','survives and reproduces outside human care','is always a single domesticated pet indoors','cannot find food without an owner','野外生存并繁殖可能带来生态管理问题。'),Q('feral',4,1,'The closest contrast to a feral cat is a?','domesticated house cat','wild-living stray cat','untamed animal','domesticated 与野化相对。')]);
P('ferment','ferment 经古法语源自拉丁语 fermentum“发酵剂”，可作动词指微生物使糖转化，也可指发酵过程或政治动荡。',C('ferment.s1','食品制作','The brewer lets the grain mixture ferment at a controlled temperature, allowing yeast to convert sugars before the liquid is filtered.','酿酒师让谷物混合物在受控温度下发酵，使酵母先把糖转化，然后再过滤液体。','The brewer lets the grain mixture ferment at a controlled temperature / allowing yeast to convert sugars / before the liquid is filtered.','let + 宾语 + ferment 表示让其发酵；allowing 说明酵母的作用。','酵母将糖转化的过程是生物发酵，符合动词义 s1。'),M('The brewer fermented the drink by sterilizing it and preventing yeast or bacteria from acting.','The brewer preserved the drink by sterilizing it and preventing yeast or bacteria from acting.','杀灭微生物会阻止发酵，不能称为让饮品 ferment。'),[Q('ferment',1,1,'When yeast ferments sugar, it?','converts it into products such as alcohol or carbon dioxide','turns it into metal','removes every molecule of water instantly','酵母发酵会把糖转化成酒精或二氧化碳等。'),Q('ferment',2,2,'A period of political ferment is a period of?','intense unrest and change','complete political silence','routine weather measurement','名词 ferment 也可指政治动荡。'),Q('ferment',3,1,'Which action allows dough to ferment?','letting microorganisms act under suitable conditions','boiling it to kill all yeast immediately','keeping it frozen solid forever','适当条件下微生物活动使面团发酵。'),Q('ferment',4,1,'In food production, ferment is closest to?','undergo microbial transformation','freeze without any change','grind into dry powder','此处 ferment 指微生物引起的转化。')]);
P('fermentation','fermentation 由 ferment 加 -ation 构成，指微生物把糖转化为气体、酒精或酸等产物的过程。',C('fermentation.s1','食品科学','During fermentation, the dough released bubbles as microorganisms produced carbon dioxide, and the baker waited until it had risen before shaping the loaves.','发酵过程中，微生物产生二氧化碳，使面团冒出气泡；面包师等它发起来后才整形。','During fermentation / the dough released bubbles / as microorganisms produced carbon dioxide / and the baker waited until it had risen before shaping the loaves.','fermentation 是过程名词；as 引出微生物产气的机制。','微生物产气并使面团膨起，体现 fermentation 过程。'),M('Fermentation stopped because bacteria produced gas and acid from sugar.','Fermentation began because bacteria produced gas and acid from sugar.','微生物把糖转化并产气产酸正是发酵发生，而非停止。'),[Q('fermentation',1,1,'Fermentation is a process in which microorganisms?','convert sugars into substances such as gas, alcohol, or acid','turn rocks into metal tools','remove every nutrient from water','微生物转化糖并产出气体、酒精或酸。'),Q('fermentation',2,1,'Bubbles in rising bread dough often come from?','carbon dioxide produced during fermentation','oxygen frozen inside the flour','steam trapped before the dough was mixed','发酵产生的二氧化碳形成气泡。'),Q('fermentation',3,1,'Which food relies on fermentation?','yogurt made by bacterial cultures','plain ice cubes','unprocessed table salt','酸奶依靠细菌发酵制成。'),Q('fermentation',4,1,'A fermentation tank is designed to?','provide controlled conditions for microbial activity','measure the height of a building','store dry clothes away from sunlight','发酵罐为微生物活动提供可控条件。')]);
P('fern','fern 源自古英语 fearn，指不以花和种子繁殖、通常以孢子繁殖的蕨类植物，也可指栽种作观赏植物的蕨。',C('fern.s2','室内园艺','She placed the ornamental fern near a humid window, where its arching fronds received indirect light without drying in direct afternoon sun.','她把观赏蕨放在湿润的窗边，让弯垂的叶片接受间接光照，避免被下午直射阳光晒干。','She placed the ornamental fern near a humid window / where its arching fronds received indirect light / without drying in direct afternoon sun.','fern 作植物名词；ornamental 表明此处是栽培观赏蕨的 s2。','窗边盆栽用于装饰，体现观赏蕨义。'),M('The fern was a flowering tree that produced apples from its branches every spring.','The fern was a non-flowering plant with divided fronds.','蕨类不结果实，不会长出苹果；它是无花植物。'),[Q('fern',1,1,'A fern is a plant that commonly reproduces by?','spores rather than flowers and seeds','apples growing on branches','tiny metal beads','蕨类通常以孢子繁殖。'),Q('fern',2,2,'An ornamental fern is grown mainly for?','its decorative foliage','its edible fruit harvest','its ability to produce wool','观赏蕨主要因叶片而栽培。'),Q('fern',3,1,'Which setting might suit a fern?','a damp, shady woodland floor','a dry desert with no shade','a deep ocean trench without light','蕨类常见于潮湿阴凉处。'),Q('fern',4,1,'The divided leaves of a fern are often called?','fronds','petals','scales','蕨类的叶状结构称 fronds。')]);
P('ferocious','ferocious 由拉丁语 ferox“凶猛的”进入英语，形容像野兽般猛烈残暴，也可描述风暴、竞争等强烈激烈。',C('ferocious.s2','竞技强度','The two teams fought a ferocious battle for the championship, trading goals until the final minute despite their exhaustion.','两队为冠军展开激烈较量，即使精疲力尽，仍一直互有进球，直到最后一分钟。','The two teams fought a ferocious battle for the championship / trading goals / until the final minute / despite their exhaustion.','ferocious 修饰 battle，作比喻表示极其激烈；trading goals 展示竞争强度。','持续到最后的高强度竞争，符合激烈义 s2。'),M('The ferocious storm brought calm skies, no wind, and perfectly still water.','The gentle weather brought calm skies, no wind, and perfectly still water.','平静无风与凶猛猛烈的 ferocious 风暴相反。'),[Q('ferocious',1,1,'A ferocious animal is?','violent and frightening','gentle and harmless','small but silent','ferocious 表示凶猛、令人害怕。'),Q('ferocious',2,2,'A ferocious debate is?','extremely intense and forceful','quiet and without disagreement','a discussion about animal fur only','ferocious 可比喻争论激烈。'),Q('ferocious',3,1,'Which competition is ferocious?','rivals exchange powerful attacks until the final seconds','one player wins by default without an opponent','participants take turns reading quietly','强烈攻防、竞争到最后体现激烈。'),Q('ferocious',4,1,'Choose the closest opposite of ferocious.','mild','violent','fierce','mild 与猛烈、凶猛相反。')]);
P('ferocity','ferocity 由 ferocious 加 -ity 构成，指凶猛残暴的程度，也可比喻风暴或冲突等表现出的强烈力量。',C('ferocity.s1','冲突报道','The report described the fire’s ferocity as it swept through dry grass, melted roadside signs, and forced residents to evacuate overnight.','报告描述了火势的猛烈：大火席卷干草、熔化路边标志牌，并迫使居民连夜撤离。','The report described the fire’s ferocity / as it swept through dry grass / melted roadside signs / and forced residents to evacuate overnight.','ferocity 表示猛烈程度；后面列举的破坏和撤离说明强度。','火势造成巨大破坏并迫使撤离，显示其猛烈程度。'),M('The storm’s ferocity was shown by its complete calm, with no damage and no movement of air.','The storm’s mildness was shown by its complete calm, with no damage and no movement of air.','毫无破坏的平静天气说明温和，而非 ferocity。'),[Q('ferocity',1,1,'The ferocity of a wild animal refers to its?','savage violence or force','ability to imitate human speech','preference for sleeping in shade','ferocity 指凶猛、狂暴的程度。'),Q('ferocity',2,1,'The ferocity of a storm can be seen in?','destructive winds tearing roofs away','a light breeze moving one leaf','a clear sky with no weather change','摧毁屋顶的强风显示风暴猛烈。'),Q('ferocity',3,1,'A debate conducted with ferocity is?','intensely forceful and aggressive','slow and entirely silent','unrelated to any disagreement','ferocity 也可表示冲突的激烈强度。'),Q('ferocity',4,1,'The closest contrast to ferocity is?','gentleness','savagery','intensity','gentleness 与凶猛相反。')]);
P('ferret','ferret 的动物义来自早期法语和拉丁语对小型穴猎动物的称呼；动词 ferret out 指费力查出隐情，ferret about 则指翻找。',C('ferret.s2','资料调查','The auditor ferreted out a duplicate payment by comparing archived invoices with the bank records rather than relying on the summary sheet.','审计员通过比较存档发票和银行记录，而不是只看汇总表，费力查出了一笔重复付款。','The auditor ferreted out a duplicate payment / by comparing archived invoices with the bank records / rather than relying on the summary sheet.','ferret out + 隐藏信息表示费力查明；by 引出查找方法。','审计员从记录中追查出隐藏的重复付款，符合 s2。'),M('The auditor ferreted out the duplicate payment by refusing to inspect any invoice or account record.','The auditor overlooked the duplicate payment by refusing to inspect any invoice or account record.','拒绝查看记录无法查出隐藏问题，应称 overlook。'),[Q('ferret',1,2,'To ferret out a hidden error is to?','search persistently until it is found','bury it under new paperwork','announce it before checking','ferret out 表示费力查出隐藏事物。'),Q('ferret',2,1,'A ferret is a small animal often used for?','hunting rabbits in burrows','growing on damp rocks','measuring wind speed','雪貂曾用于追猎洞中的兔子。'),Q('ferret',3,3,'If someone ferrets about in a drawer, the person is?','searching through it by moving things around','locking it without opening it','painting the drawer from outside','ferret about 指翻找、搜索。'),Q('ferret',4,2,'Which phrase is a common verb pattern?','ferret out the truth','ferret at the truth on','ferret to be truthfully','ferret out 常与 hidden facts、truth 等搭配。')]);
P('ferromagnetic','ferromagnetic 由 ferro-（铁）和 magnetic（磁性的）构成，指铁等材料能够强烈磁化并可保留磁性的性质。',C('ferromagnetic.s1','材料实验','The technician placed the ferromagnetic sample near a magnet and measured how strongly it aligned with the applied field.','技术员把铁磁性样品放在磁铁附近，测量它与外加磁场对齐的程度。','The technician placed the ferromagnetic sample near a magnet / and measured how strongly it aligned / with the applied field.','ferromagnetic 作材料性质形容词；aligned with the field 描述受磁场影响。','样品能显著响应外加磁场，体现铁磁性。'),M('Copper is ferromagnetic because it becomes a strong permanent magnet under ordinary conditions.','Iron is ferromagnetic because it can become strongly magnetized under suitable conditions.','普通铜不是铁磁材料；铁是常见铁磁材料。'),[Q('ferromagnetic',1,1,'A ferromagnetic material can?','become strongly magnetized','never interact with a magnetic field','turn into a living organism','ferromagnetic 指能够强烈磁化的材料。'),Q('ferromagnetic',2,1,'Which familiar metal is ferromagnetic?','iron','aluminum foil in every form','pure copper under ordinary conditions','铁是典型铁磁材料。'),Q('ferromagnetic',3,1,'A ferromagnetic sample may?','retain magnetization after an external field is removed','become transparent in sunlight','dissolve immediately in dry air','铁磁材料可保留部分磁化。'),Q('ferromagnetic',4,1,'The prefix ferro- in ferromagnetic refers to?','iron','water','wood','ferro- 源自表示铁的词根。')]);
P('fertilise','fertilise 是英式拼法，动词由 fertile 加 -ise 构成，可指给土壤施肥，也可指使卵子或植物胚珠受精。',C('fertilise.s2','生物学实验','In the laboratory, the researcher used a microscope to observe how a pollen grain could fertilise the ovule of the flowering plant.','在实验室里，研究人员用显微镜观察花粉粒如何使开花植物的胚珠受精。','In the laboratory / the researcher used a microscope to observe / how a pollen grain could fertilise the ovule / of the flowering plant.','英式拼写 fertilise 作动词；fertilise an ovule 表示使胚珠受精。','花粉粒与胚珠发生生殖过程，符合生物学受精义 s2。'),M('The pollen fertilised the ovule by preventing it from developing and stopping reproduction.','The pollen failed to fertilise the ovule, preventing it from developing.','阻止胚珠发育表示没有成功受精，而不是完成 fertilise。'),[Q('fertilise',1,2,'In plant biology, pollen fertilises an ovule when it?','enables the ovule to begin developing','removes every seed from the flower','turns the ovule into soil','fertilise 可指使植物胚珠开始发育。'),Q('fertilise',2,1,'A farmer may fertilise a field by?','adding nutrients to its soil','removing every source of plant nutrition','painting the crops blue','农业义 fertilise 表示给土地施肥。'),Q('fertilise',3,2,'Which sentence uses fertilise in the reproductive sense?','Sperm can fertilise an egg cell.','The gardener fertilised the lawn with compost.','The farmer bought fertiliser for the orchard.','精子使卵子受精是生殖义。'),Q('fertilise',4,1,'Fertilise is the usual British spelling of?','fertilize','fertilizer','fertility','英式动词 fertilise 对应美式 fertilize。')]);
P('fertiliser','fertiliser 是英式拼法，fertilise + -er 构成名词，指施入土壤、提供植物养分的天然或化学物质。',C('fertiliser.s1','农业用量','The farmer applied fertiliser according to the soil test, avoiding excess nutrients that could wash into the nearby river after heavy rain.','农场主根据土壤检测结果施肥，避免养分过量后在暴雨时流入附近河流。','The farmer applied fertiliser according to the soil test / avoiding excess nutrients / that could wash into the nearby river / after heavy rain.','英式 fertiliser 是肥料名词；apply fertiliser to soil 是常见搭配。','施入土壤以提供植物养分的物质即肥料。'),M('The farmer called clean rainwater a fertiliser because it supplied no nutrients and was never added to soil.','The farmer called the nutrient-rich compost a fertiliser because it supplied nutrients to the soil.','不含养分且未施入土壤的雨水不是肥料。'),[Q('fertiliser',1,1,'A fertiliser is used to?','supply nutrients to soil or plants','remove every seed from a crop','measure the temperature of a barn','fertiliser 指提供植物养分的肥料。'),Q('fertiliser',2,1,'Which item could be a natural fertiliser?','composted manure','a clean glass bottle','a steel fence post','腐熟粪肥能为土壤提供养分。'),Q('fertiliser',3,1,'Why should fertiliser use follow a soil test?','to provide needed nutrients without excessive runoff','to guarantee that rivers receive more chemicals','to prevent plants from receiving any minerals','根据检测施肥可满足需求并减少过量径流。'),Q('fertiliser',4,1,'Fertiliser is the British spelling of?','fertilizer','fertilize','fertile','fertiliser 是名词的英式拼法。')]);



})();
